'use client';

import { forwardRef, useImperativeHandle, useState, useEffect, useRef } from 'react';
import { useForm, useFieldArray, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Clock, DollarSign, Info, Percent, Plus, TrendingUp, X } from 'lucide-react';
import Cleave from 'cleave.js/react';
import { cn } from '@/lib/utils';
import { formatBRL, formatDateMask, parseBRL, parsePct, toBRLInput } from '../../utils';
import { SCENARIO_TAB_COLORS } from '@/components/PostAquisition/financial/IndividualCards/constants';
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select';
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog';
import type { CessionarioRow } from './types';
import {
    CESS_COLORS,
    CLEAVE_BRL_OPTS,
    LOA_OPTIONS,
    TIPOS_CUSTO_PADRAO,
    monthsBetween,
    parseDateBR,
} from './constants';
import { CAMPO_PREVISAO_POR_CENARIO } from '@/functions/finance/previsao-cenarios';
import { step3Schema, step3SchemaEdit, type Step3Values, type StepHandle } from './schemas';

interface StepPrecificacaoProps {
    mode?: 'create' | 'edit';
    defaultValues?: Step3Values;
    onValidSubmit: (data: Step3Values) => void;
    onValidityChange?: (isValid: boolean) => void;
    onDirtyChange?: (isDirty: boolean) => void;
    // cross-step (read-only, vêm do orquestrador)
    cessionarios: CessionarioRow[];
    valorLiquido: number;
    totalPct: number;
}

/** Campos que o backend valida (CEN-11/CEN-12) e o input correspondente aqui. */
const CAMPO_DO_FORM_POR_CAMPO_API: Record<string, keyof Step3Values | undefined> = {
    [CAMPO_PREVISAO_POR_CENARIO.base]: 'dataPrevisaoPagamento',
    [CAMPO_PREVISAO_POR_CENARIO.optimistic]: 'dataPrevisaoPagamentoOtimista',
    [CAMPO_PREVISAO_POR_CENARIO.conservative]: 'dataPrevisaoPagamentoConservador',
    data_de_aquisicao_manual: 'dataAquisicao',
    data_aquisicao: 'dataAquisicao',
};

/** No cadastro só estes dois aparecem na tela; ver `step3Schema`. */
const CAMPOS_VISIVEIS_NO_CADASTRO = new Set<keyof Step3Values>([
    'dataPrevisaoPagamento',
    'dataAquisicao',
]);

const labelClass =
    'text-[9px] font-semibold text-[#888] uppercase mb-0.5 dark:text-zinc-400';
const inputClass =
    'w-full h-8 px-2 py-0 text-xs rounded-md border border-border bg-white outline-none transition-colors focus:border-app-default focus:ring-1 focus:ring-app-default/20 dark:border-white/15 dark:bg-boxdark dark:text-foreground dark:placeholder:text-zinc-500 dark:hover:border-white/25 dark:focus:border-app-default dark:focus:ring-app-default/30';

const DEFAULT_VALUES: Step3Values = {
    valorCedente: '',
    comissaoBroker: '',
    comissaoBrokerAtivo: '',
    comissaoAtivos: '',
    custosExtras: [],
    tiposCustom: [],
    dataAquisicao: '',
    dataPrevisaoPagamento: '',
    dataPrevisaoPagamentoOtimista: '',
    dataPrevisaoPagamentoConservador: '',
    loa: '',
};

function FieldError({ message }: { message?: string }) {
    if (!message) return null;
    return <p className="mt-0.5 text-[9px] font-medium text-red-500">{message}</p>;
}

/** Linha do card de previsões — a palavra do cenário recebe a cor da pós-aquisição. */
function PrevisaoPagamentoRow({
    cenario,
    color,
    required,
    value,
    error,
    onChange,
}: {
    cenario: string;
    color: string;
    required?: boolean;
    value: string;
    error?: string;
    onChange: (value: string) => void;
}) {
    return (
        <div className="flex flex-col gap-2 rounded-md border border-border bg-white px-3 py-2.5 sm:flex-row sm:items-center sm:justify-between dark:border-border/60 dark:bg-boxdark-2">
            <label
                className={cn(
                    labelClass,
                    'mb-0 flex items-center gap-1.5',
                    error && 'text-red-500',
                )}
            >
                <span
                    className="size-2 shrink-0 rounded-full"
                    style={{ backgroundColor: color }}
                    aria-hidden
                />
                Data de Pagamento{' '}
                <span className="font-extrabold" style={{ color }}>
                    {cenario}
                </span>
                {required && <span className="text-red-500">*</span>}
            </label>
            <div className="w-full sm:w-44">
                <input
                    type="text"
                    className={cn(inputClass, error && 'border-red-400')}
                    value={value}
                    onChange={(e) => onChange(formatDateMask(e.target.value))}
                    placeholder="DD/MM/AAAA"
                />
                <FieldError message={error} />
            </div>
        </div>
    );
}

export const StepPrecificacao = forwardRef<StepHandle, StepPrecificacaoProps>(
    (
        {
            mode = 'create',
            defaultValues,
            onValidSubmit,
            onValidityChange,
            onDirtyChange,
            cessionarios,
            valorLiquido,
            totalPct,
        },
        ref,
    ) => {
        // ── State UI-only (rateio) ────────────────────────────────────────────
        const [showRateio, setShowRateio] = useState(false);
        const [rateio, setRateio] = useState<Record<string, Record<string, string>>>({});
        const [isNovoTipoModalOpen, setIsNovoTipoModalOpen] = useState(false);
        const [novoTipoNome, setNovoTipoNome] = useState('');
        const pendingTipoOnChangeRef = useRef<((value: string) => void) | null>(null);

        const form = useForm<Step3Values>({
            resolver: zodResolver(mode === 'edit' ? step3SchemaEdit : step3Schema),
            defaultValues: defaultValues ?? DEFAULT_VALUES,
            mode: 'onSubmit',
            reValidateMode: 'onChange',
        });

        useEffect(() => {
            form.reset(defaultValues ?? DEFAULT_VALUES);
        }, [defaultValues, form]);

        const {
            control,
            watch,
            getValues,
            setValue,
            formState: { errors, isValid, isDirty },
        } = form;

        useEffect(() => {
            onValidityChange?.(isValid);
        }, [isValid, onValidityChange]);

        const onDirtyChangeRef = useRef(onDirtyChange);
        onDirtyChangeRef.current = onDirtyChange;
        useEffect(() => {
            onDirtyChangeRef.current?.(isDirty);
            // eslint-disable-next-line react-hooks/exhaustive-deps
        }, [isDirty]);

        useImperativeHandle(ref, () => ({
            submit: () => {
                form.handleSubmit(onValidSubmit)();
            },
            isDirty: () => isDirty,
            resetDirty: () => form.reset(form.getValues()),
            aplicarErrosDaApi: (errosPorCampo) => {
                let primeiroCampo: keyof Step3Values | null = null;

                for (const [campoApi, mensagem] of Object.entries(errosPorCampo)) {
                    const campo = CAMPO_DO_FORM_POR_CAMPO_API[campoApi];
                    if (!campo) continue;
                    // No cadastro, otimista e conservadora não são renderizadas:
                    // marcá-las deixaria o erro invisível e ainda suprimiria o toast.
                    if (mode !== 'edit' && !CAMPOS_VISIVEIS_NO_CADASTRO.has(campo)) continue;

                    form.setError(campo, { type: 'manual', message: mensagem });
                    primeiroCampo ??= campo;
                }

                if (!primeiroCampo) return false;

                form.setFocus(primeiroCampo);
                return true;
            },
        }));

        const {
            fields: custosFields,
            append: appendCusto,
            remove: removeCusto,
        } = useFieldArray({
            control,
            name: 'custosExtras',
        });

        // ── Valores observados ────────────────────────────────────────────────
        const valorCedente = watch('valorCedente');
        const comissaoBroker = watch('comissaoBroker');
        const comissaoBrokerAtivo = watch('comissaoBrokerAtivo');
        const comissaoAtivos = watch('comissaoAtivos');
        const custosExtras = watch('custosExtras') ?? [];
        const tiposCustom = watch('tiposCustom') ?? [];
        const dataAquisicao = watch('dataAquisicao');
        const dataPrevisaoPagamento = watch('dataPrevisaoPagamento');
        const dataPrevisaoPagamentoOtimista = watch('dataPrevisaoPagamentoOtimista');
        const dataPrevisaoPagamentoConservador = watch('dataPrevisaoPagamentoConservador');
        const loa = watch('loa');

        // ── Valores computados ────────────────────────────────────────────────
        const valorCedenteNum = parseBRL(valorCedente ?? '');
        const comissaoBrokerNum = parseBRL(comissaoBroker ?? '');
        const comissaoBrokerAtivoNum = parseBRL(comissaoBrokerAtivo ?? '');
        const comissaoAtivosNum = parseBRL(comissaoAtivos ?? '');
        const totalCustosExtras = custosExtras.reduce((s, c) => s + (c.valor ?? 0), 0);
        const totalInvestimento =
            valorCedenteNum +
            comissaoBrokerNum +
            comissaoBrokerAtivoNum +
            comissaoAtivosNum +
            totalCustosExtras;
        const precoAquisicao =
            valorLiquido > 0 && totalInvestimento > 0
                ? ((totalInvestimento / valorLiquido) * 100).toFixed(2)
                : null;

        const mesesEntre =
            dataAquisicao && dataPrevisaoPagamento
                ? (() => {
                      const d1 = parseDateBR(dataAquisicao);
                      const d2 = parseDateBR(dataPrevisaoPagamento ?? '');
                      return d1 && d2 ? monthsBetween(d1, d2) : null;
                  })()
                : null;

        // ── Rateio helpers ────────────────────────────────────────────────────
        function getCostColumns() {
            const fixed = [
                { key: 'cedente', label: 'Vlr Cedente', globalVal: valorCedenteNum },
                { key: 'broker', label: 'Com. Broker Investidor', globalVal: comissaoBrokerNum },
                {
                    key: 'brokerAtivo',
                    label: 'Com. Broker Ativo',
                    globalVal: comissaoBrokerAtivoNum,
                },
                { key: 'ativos', label: 'Com. Ativos', globalVal: comissaoAtivosNum },
            ];
            const extras = custosExtras.map((c, idx) => ({
                key: `extra_${idx}`,
                label: c.descricao || 'Custo',
                globalVal: c.valor ?? 0,
            }));
            return [...fixed, ...extras];
        }

        function buildRateio(): Record<string, Record<string, string>> {
            const formValues = getValues();
            const valorCedenteAtual = parseBRL(formValues.valorCedente ?? '');
            const comissaoBrokerAtual = parseBRL(formValues.comissaoBroker ?? '');
            const comissaoBrokerAtivoAtual = parseBRL(formValues.comissaoBrokerAtivo ?? '');
            const comissaoAtivosAtual = parseBRL(formValues.comissaoAtivos ?? '');
            const custosExtrasAtuais = formValues.custosExtras ?? [];

            const cols = [
                { key: 'cedente', label: 'Vlr Cedente' },
                { key: 'broker', label: 'Com. Broker Investidor' },
                { key: 'brokerAtivo', label: 'Com. Broker Ativo' },
                { key: 'ativos', label: 'Com. Ativos' },
                ...custosExtrasAtuais.map((c, idx) => ({
                    key: `extra_${idx}`,
                    label: c.descricao || 'Custo',
                })),
            ];

            const globalValues: Record<string, number> = {
                cedente: valorCedenteAtual,
                broker: comissaoBrokerAtual,
                brokerAtivo: comissaoBrokerAtivoAtual,
                ativos: comissaoAtivosAtual,
                ...Object.fromEntries(
                    custosExtrasAtuais.map((c, idx) => [`extra_${idx}`, c.valor ?? 0]),
                ),
            };
            const result: Record<string, Record<string, string>> = {};
            cessionarios.forEach((c) => {
                const pct = parsePct(c.pct);
                const valores: Record<string, string> = {};
                cols.forEach((col) => {
                    valores[col.key] = toBRLInput((globalValues[col.key] ?? 0) * (pct / 100));
                });
                result[c.id] = valores;
            });
            return result;
        }

        function updateRateioVal(cessId: string, key: string, val: string) {
            setRateio((prev) => ({
                ...prev,
                [cessId]: { ...(prev[cessId] ?? {}), [key]: val },
            }));
        }

        function resetRateio() {
            setRateio(buildRateio());
        }

        function handleToggleRateio() {
            if (!showRateio) setRateio(buildRateio());
            setShowRateio((v) => !v);
        }

        function openNovoTipoModal(onChange: (value: string) => void) {
            pendingTipoOnChangeRef.current = onChange;
            setNovoTipoNome('');
            setIsNovoTipoModalOpen(true);
        }

        function handleConfirmNovoTipo() {
            const nome = novoTipoNome.trim();
            if (!nome) return;

            const existing =
                tiposCustom.find((t) => t.toLowerCase() === nome.toLowerCase()) ?? null;
            const finalTipo = existing ?? nome;

            if (!existing) {
                setValue('tiposCustom', [...tiposCustom, nome], { shouldValidate: true });
            }

            pendingTipoOnChangeRef.current?.(finalTipo);
            setIsNovoTipoModalOpen(false);
            setNovoTipoNome('');
            pendingTipoOnChangeRef.current = null;
        }

        const rateioRecalcSignature = [
            valorCedenteNum,
            comissaoBrokerNum,
            comissaoBrokerAtivoNum,
            comissaoAtivosNum,
            cessionarios.map((c) => `${c.id}:${c.pct}`).join('|'),
            custosExtras.map((c, idx) => `${idx}:${c.descricao ?? ''}:${c.valor ?? 0}`).join('|'),
        ].join('||');

        useEffect(() => {
            if (!showRateio) return;

            const timer = window.setTimeout(() => {
                setRateio(buildRateio());
            }, 2000);

            return () => window.clearTimeout(timer);
            // Debounce para não recalcular o rateio a cada tecla enquanto o usuário digita.
        }, [showRateio, rateioRecalcSignature]);

        function getRateioValidation() {
            if (!showRateio || Object.keys(rateio).length === 0) return [];
            const globalValues: Record<string, number> = {
                cedente: valorCedenteNum,
                broker: comissaoBrokerNum,
                brokerAtivo: comissaoBrokerAtivoNum,
                ativos: comissaoAtivosNum,
                ...Object.fromEntries(custosExtras.map((c, idx) => [`extra_${idx}`, c.valor ?? 0])),
            };
            const cols = getCostColumns();
            const totalPctFactor = Math.min(totalPct, 100) / 100;
            return cols
                .map((col) => {
                    const expected = (globalValues[col.key] ?? 0) * totalPctFactor;
                    const sumRateio = cessionarios.reduce(
                        (s, c) => s + parseBRL(rateio[c.id]?.[col.key] ?? ''),
                        0,
                    );
                    const match = Math.abs(sumRateio - expected) < 0.01;
                    return { ...col, expected, sumRateio, match };
                })
                .filter((v) => !v.match && v.expected > 0);
        }

        return (
            <>
                <div className="rounded-xl border border-border bg-gray-50 p-5 dark:border-white/10 dark:bg-boxdark dark:shadow-sm dark:shadow-black/20">
                    <div className="grid grid-cols-1 gap-6 lg:grid-cols-5 lg:items-start">
                        {/* ── Seção: Precificação ─────────────────────────────── */}
                        <div className="rounded-lg border border-border bg-white p-4 shadow-sm dark:border-white/10 dark:bg-boxdark-2 dark:shadow-none lg:col-span-3 lg:row-start-1">
                            <div className="mb-4 flex items-center gap-2 border-b border-border/50 pb-3 dark:border-white/10">
                                <div className="bg-app-default/10 flex h-7 w-7 items-center justify-center rounded-md dark:bg-app-default/15">
                                    <TrendingUp className="h-3.5 w-3.5 text-app-default" />
                                </div>
                                <h3 className="text-xs font-bold uppercase tracking-wide text-foreground">
                                    Precificação
                                </h3>
                            </div>

                            {/* Grid de inputs */}
                            <div className="mb-5 grid grid-cols-2 gap-x-4 gap-y-4 lg:grid-cols-3">
                                {/* Valor Cedente */}
                                <div className="flex flex-col">
                                    <label
                                        className={cn(
                                            labelClass,
                                            'flex items-center gap-1',
                                            errors.valorCedente && 'text-red-500',
                                        )}
                                    >
                                        Valor Cedente <span className="text-red-500">*</span>
                                    </label>
                                    <Cleave
                                        className={cn(
                                            inputClass,
                                            errors.valorCedente &&
                                                'border-red-400 focus:border-red-400 focus:ring-red-200'
                                        )}
