                                        Data de Aquisição <span className="text-red-500">*</span>
                                    </label>
                                    <input
                                        type="text"
                                        className={cn(
                                            inputClass,
                                            errors.dataAquisicao && 'border-red-400'
                                        )}
                                        value={dataAquisicao ?? ''}
                                        onChange={(e) =>
                                            setValue(
                                                'dataAquisicao',
                                                formatDateMask(e.target.value),
                                                { shouldValidate: true, shouldDirty: true },
                                            )
                                        }
                                        placeholder="DD/MM/AAAA"
                                    />
                                    <FieldError message={errors.dataAquisicao?.message} />
                                </div>
                                <div>
                                    <label
                                        className={cn(
                                            labelClass,
                                            'flex items-center gap-1',
                                            errors.loa && 'text-red-500',
                                        )}
                                    >
                                        LOA <span className="text-red-500">*</span>
                                    </label>
                                    <Controller
                                        control={control}
                                        name="loa"
                                        render={({ field: f }) => (
                                            <Select
                                                value={f.value ?? ''}
                                                onValueChange={f.onChange}
                                            >
                                                <SelectTrigger
                                                    className={cn(
                                                        'h-8 w-full border-border text-xs normal-case tracking-normal dark:border-white/15 dark:bg-boxdark dark:text-foreground dark:hover:border-white/25',
                                                        errors.loa && 'border-red-400'
                                                    )}
                                                >
                                                    <SelectValue placeholder="Selecione a LOA" />
                                                </SelectTrigger>
                                                <SelectContent>
                                                    {LOA_OPTIONS.map((opt) => (
                                                        <SelectItem
                                                            key={opt}
                                                            value={opt}
                                                            className="normal-case tracking-normal"
                                                        >
                                                            {opt}
                                                        </SelectItem>
                                                    ))}
                                                </SelectContent>
                                            </Select>
                                        )}
                                    />
                                    <FieldError message={errors.loa?.message} />
                                </div>
                                <div>
                                    <label className={cn(labelClass, 'flex items-center gap-1')}>
                                        Prazo (Meses)
                                        <span className="text-[9px] text-muted-foreground">
                                            — Calculado pelas datas
                                        </span>
                                    </label>
                                    <div
                                        className={cn(
                                            'flex h-8 items-center rounded-md border px-3 text-xs',
                                            mesesEntre !== null
                                                ? 'border-blue-200 bg-blue-50 font-semibold text-blue-700 dark:border-blue-800/40 dark:bg-blue-950/20 dark:text-blue-400'
                                                : 'border-border bg-muted/30 text-muted-foreground dark:border-white/10 dark:bg-white/5',
                                        )}
                                    >
                                        {mesesEntre !== null ? (
                                            <>{mesesEntre} meses</>
                                        ) : (
                                            <span>—</span>
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Card de previsões de pagamento — otimista, base e conservadora */}
                            <div className="mt-4 rounded-lg border border-border bg-gray-50/70 p-3 dark:border-border/60 dark:bg-boxdark">
                                <p className="mb-3 text-[10px] font-bold uppercase tracking-wider text-muted-foreground">
                                    Datas de previsão de pagamento
                                </p>
                                <div className="flex flex-col gap-2.5">
                                    {mode === 'edit' && (
                                        <PrevisaoPagamentoRow
                                            cenario="Otimista"
                                            color={SCENARIO_TAB_COLORS.optimistic}
                                            value={dataPrevisaoPagamentoOtimista ?? ''}
                                            error={errors.dataPrevisaoPagamentoOtimista?.message}
                                            onChange={(value) =>
                                                setValue('dataPrevisaoPagamentoOtimista', value, {
                                                    shouldValidate: true,
                                                    shouldDirty: true,
                                                })
                                            }
                                        />
                                    )}
                                    <PrevisaoPagamentoRow
                                        cenario="Estimada (Base)"
                                        color={SCENARIO_TAB_COLORS.base}
                                        required
                                        value={dataPrevisaoPagamento ?? ''}
                                        error={errors.dataPrevisaoPagamento?.message}
                                        onChange={(value) =>
                                            setValue('dataPrevisaoPagamento', value, {
                                                shouldValidate: true,
                                                shouldDirty: true,
                                            })
                                        }
                                    />
                                    {mode === 'edit' && (
                                        <PrevisaoPagamentoRow
                                            cenario="Conservadora"
                                            color={SCENARIO_TAB_COLORS.conservative}
                                            value={dataPrevisaoPagamentoConservador ?? ''}
                                            error={errors.dataPrevisaoPagamentoConservador?.message}
                                            onChange={(value) =>
                                                setValue(
                                                    'dataPrevisaoPagamentoConservador',
                                                    value,
                                                    { shouldValidate: true, shouldDirty: true },
                                                )
                                            }
                                        />
                                    )}
                                </div>
                                {mode === 'edit' && (
                                    <div className="mt-3 flex items-start gap-2 rounded-md border border-blue-200 bg-blue-50 px-3 py-2 dark:border-blue-800/30 dark:bg-blue-950/20">
                                        <Info className="mt-px h-3 w-3 shrink-0 text-blue-600 dark:text-blue-400" />
                                        <p className="text-[10px] leading-relaxed text-blue-700 dark:text-blue-400">
                                            Se você não informar as datas otimista e conservadora,
                                            serão aplicadas as regras do smart block para esses
                                            cenários.
                                        </p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Campo hidden para suprimir warning de loa unused */}
                    <input type="hidden" value={loa ?? ''} readOnly />
                </div>

                <Dialog
                    open={isNovoTipoModalOpen}
                    onOpenChange={(open) => {
                        setIsNovoTipoModalOpen(open);
                        if (!open) {
                            setNovoTipoNome('');
                            pendingTipoOnChangeRef.current = null;
                        }
                    }}
                >
                    <DialogContent className="sm:max-w-md">
                        <DialogHeader>
                            <DialogTitle>Cadastrar novo tipo de custo</DialogTitle>
                            <DialogDescription>
                                Informe o nome do novo tipo para adicionar na lista de custos.
                            </DialogDescription>
                        </DialogHeader>
                        <div className="py-2">
                            <label className={labelClass}>Nome do tipo</label>
                            <input
                                className={inputClass}
                                value={novoTipoNome}
                                onChange={(e) => setNovoTipoNome(e.target.value)}
                                placeholder="Ex: Custas de cartório"
                                autoFocus
                            />
                        </div>
                        <DialogFooter>
                            <button
                                type="button"
                                onClick={() => setIsNovoTipoModalOpen(false)}
                                className="rounded-md border border-border px-3 py-2 text-xs font-semibold text-muted-foreground hover:bg-muted/40 dark:border-white/10 dark:hover:bg-white/5"
                            >
                                Cancelar
                            </button>
                            <button
                                type="button"
                                onClick={handleConfirmNovoTipo}
                                disabled={!novoTipoNome.trim()}
                                className="rounded-md bg-app-default px-3 py-2 text-xs font-semibold text-white disabled:cursor-not-allowed disabled:opacity-50"
                            >
                                Cadastrar tipo
                            </button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            </>
        );
    },
);

StepPrecificacao.displayName = 'StepPrecificacao';

