'use client';

import { useRef, useMemo, useState } from 'react';
import { ArrowLeft, ExternalLink, CheckCircle, Loader2 } from 'lucide-react';
import { AnimatePresence, m } from 'framer-motion';
import { LottieAnimation } from '@/components/Lottie/LottieAnimation';
import fileLoadingAiAnimation from '@/animations/icons/file-loading-ai.json';
import { Button } from '@/components/ui/button';
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog';
import { OficioForm, type OficioFormStep1Result } from '@/app/crm/broker/_components/OficioForm';
import { OficioDropzone } from '@/app/crm/broker/_components/OficioDropzone';
import { IDropzoneDocReturn } from '@/interfaces/IDropzoneDocReturn';
import type { CvldFormInputsProps } from '@/types/cvldform';
import { useQuery } from '@tanstack/react-query';
import { getOficioDetailsData } from '@/services/oficios';
import { QueryKeys } from '@/constants/query-keys';
import { mapOficioDetailsToFullForm } from '../edit-mappers';
import { formatBRL } from '../../utils';
import { apiDateToBR } from '../wizard-dates';

interface StepCalculadoraProps {
    mode?: 'create' | 'edit';
    initialFormValues?: Partial<CvldFormInputsProps> | null;
    editExtratoId?: string | null;
    onBack: () => void;
    onComplete: (result: OficioFormStep1Result) => void;
    onExitEdit?: () => void;
    isEditUnlocked?: boolean;
    unlockTapCount?: number;
    onRequestUnlockEdit?: () => void;
}

export function StepCalculadora({
    mode = 'create',
    initialFormValues = null,
    editExtratoId = null,
    onBack,
    onComplete,
    onExitEdit,
    isEditUnlocked = true,
    unlockTapCount = 0,
    onRequestUnlockEdit,
}: StepCalculadoraProps) {
    const [oficio, setOficio] = useState<IDropzoneDocReturn | null>(null);
    const [isMutationPending, setIsMutationPending] = useState(false);
    const [showDropzone, setShowDropzone] = useState(true);
    const [resumoOpen, setResumoOpen] = useState(false);
    const [pendingResult, setPendingResult] = useState<OficioFormStep1Result | null>(null);
    const hasFinalizedRef = useRef(false);

    const { data: oficioDetails, isLoading: isLoadingOficioDetails } = useQuery({
        queryKey: [QueryKeys.oficios.item, editExtratoId],
        queryFn: () => getOficioDetailsData(editExtratoId!),
        enabled: !!editExtratoId,
        staleTime: 5 * 60 * 1000,
    });

    const mergedInitialValues = useMemo<Partial<CvldFormInputsProps> | null>(() => {
        if (!editExtratoId) return initialFormValues;
        if (!oficioDetails) return initialFormValues;
        return mapOficioDetailsToFullForm(oficioDetails);
    }, [editExtratoId, initialFormValues, oficioDetails]);

    function handleDropzoneNext() {
        setShowDropzone(false);
    }

    function handleFormBack() {
        setShowDropzone(true);
    }

    function handleCalculationSuccess(result: OficioFormStep1Result) {
        hasFinalizedRef.current = false;
        setPendingResult(result);
        setResumoOpen(true);
    }

    function openMemoriaNovaAba(extratoId: string) {
        if (typeof window === 'undefined') return;
        const url = `${window.location.origin}/crm/broker/${extratoId}/memoria`;
        window.open(url, '_blank', 'noopener,noreferrer');
    }

    function finalizeParaStep2() {
        if (hasFinalizedRef.current) return;
        if (!pendingResult) {
            setResumoOpen(false);
            return;
        }
        hasFinalizedRef.current = true;
        const payload = pendingResult;
        setPendingResult(null);
        setResumoOpen(false);
        onComplete(payload);
    }

    const handleStep1Back = mode === 'edit' ? (onExitEdit ?? onBack) : onBack;

    const shouldShowForm = mode === 'edit' || !showDropzone;

    if (isLoadingOficioDetails && !!editExtratoId) {
        return (
            <div className="flex h-full flex-col items-center justify-center gap-3 rounded-xl bg-boxdark p-6">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
                <p className="text-sm text-muted-foreground">Carregando dados do ofício...</p>
            </div>
        );
    }

    if (!shouldShowForm) {
        return (
            <div className="flex h-full flex-col rounded-xl bg-boxdark p-6">
                <div className="mb-4 flex shrink-0 items-center justify-between">
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={handleStep1Back}
                        className="group/back flex items-center gap-2"
                    >
                        <ArrowLeft className="h-4 w-4 transition-transform duration-300 group-hover/back:-translate-x-1" />
                        Voltar
                    </Button>
                </div>

                <div className="flex flex-1 flex-col items-center justify-center gap-6">
                    <OficioDropzone setOficio={setOficio} handleNext={handleDropzoneNext} />

                    <div className="flex w-full max-w-2xl items-center gap-4">
                        <div className="h-px flex-1 bg-boxdark-2" />
                        <span className="shrink-0 text-sm text-subtitle">OU</span>
                        <div className="h-px flex-1 bg-boxdark-2" />
                    </div>

                    <Button onClick={handleDropzoneNext}>Preencher manualmente</Button>
                </div>
            </div>
        );
    }

    const r = pendingResult;

    return (
        <>
            <div className="relative h-full w-full rounded-xl bg-boxdark p-4">
                <OficioForm
                    oficio={oficio}
                    handlePrevious={mode === 'edit' ? handleStep1Back : handleFormBack}
                    onSuccess={handleCalculationSuccess}
                    mode={mode}
                    initialValues={mode === 'edit' ? mergedInitialValues : null}
                    extratoId={editExtratoId}
                    editUnlockEnabled={mode === 'edit'}
                    isEditUnlocked={isEditUnlocked}
                    unlockTapCount={unlockTapCount}
                    onRequestUnlockEdit={onRequestUnlockEdit}
                    suppressFeedbackOverlay
                    onStatusChange={(status) => setIsMutationPending(status === 'pending')}
                />
                <AnimatePresence>
                    {isMutationPending && (
                        <m.div
                            initial={{ height: 0, opacity: 0 }}
                            animate={{ height: '100%', opacity: 1 }}
                            exit={{ height: 0, opacity: 0 }}
                            transition={{ duration: 0.5, ease: 'easeInOut' }}
                            className="dark:bg-boxdark/95 absolute bottom-0 left-0 z-50 flex w-full flex-col items-center justify-center overflow-hidden rounded-lg bg-white/95 backdrop-blur-sm"
                        >
                            <m.div
                                initial={{ scale: 0.8, opacity: 0 }}
                                animate={{ scale: 1, opacity: 1 }}
                                className="flex flex-col items-center gap-4 p-6 text-center"
                            >
                                <LottieAnimation
                                    animationData={fileLoadingAiAnimation}
                                    width={200}
                                    height={200}
                                    loop={true}
                                    autoplay={true}
                                />
                                <h3 className="text-xl font-semibold text-title">
                                    Gerando proposta...
                                </h3>
                                <p className="text-sm text-paragraph">
                                    Aguarde enquanto processamos os dados.
                                </p>
                            </m.div>
                        </m.div>
                    )}
                </AnimatePresence>
            </div>

            <Dialog
                open={resumoOpen}
                onOpenChange={(open) => {
                    if (!open) finalizeParaStep2();
                }}
            >
                <DialogContent
                    className="max-w-md gap-6 p-6 sm:rounded-2xl"
                    onPointerDownOutside={(e) => e.preventDefault()}
                >
                    <DialogHeader className="flex flex-col items-center gap-3 pt-2 text-center sm:text-center">
                        <div className="flex h-14 w-14 items-center justify-center rounded-full bg-primary/10">
                            <CheckCircle className="h-7 w-7 text-primary" />
                        </div>
                        <div className="space-y-1">
                            <DialogTitle className="text-xl">Cálculo concluído</DialogTitle>
                            <DialogDescription className="text-center text-sm">
                                Confira o resumo do precatório antes de seguir para o próximo passo.
                            </DialogDescription>
                        </div>
                    </DialogHeader>

                    {r && (
                        <div className="dark:bg-boxdark-2/50 rounded-xl border border-border/50 bg-muted/30 p-4">
                            <dl className="flex flex-col space-y-3.5 text-sm">
                                <div className="flex items-center justify-between">
                                    <dt className="text-muted-foreground">Data base</dt>
                                    <dd className="font-medium text-foreground">
                                        {apiDateToBR(r.dataBase ?? '') || '—'}
                                    </dd>
                                </div>
                                <div className="h-px bg-border/50" />
                                <div className="flex items-center justify-between">
                                    <dt className="text-muted-foreground">Data de requisição</dt>
                                    <dd className="font-medium text-foreground">
                                        {apiDateToBR(r.dataRequisicao ?? '') || '—'}
                                    </dd>
                                </div>
                                <div className="h-px bg-border/50" />
                                <div className="flex items-center justify-between">
                                    <dt className="text-muted-foreground">LOA</dt>
                                    <dd className="font-medium text-foreground">
                                        {r.loa != null && r.loa !== '' ? String(r.loa) : '—'}
                                    </dd>
                                </div>
                                <div className="h-px bg-border/50" />
                                <div className="flex items-center justify-between">
                                    <dt className="text-muted-foreground">Previsão de pagamento</dt>
                                    <dd className="font-medium text-foreground">
                                        {apiDateToBR(r.previsaoPagamento) ||
                                            r.previsaoPagamento ||
                                            '—'}
                                    </dd>
                                </div>
                                <div className="h-px bg-border/50" />
                                <div className="flex items-center justify-between pt-1">
                                    <dt className="font-medium text-foreground">
                                        Valor líquido do ativo
                                    </dt>
                                    <dd className="text-lg font-bold text-primary">
                                        {formatBRL(r.valorLiquido)}
                                    </dd>
                                </div>
                            </dl>
                        </div>
                    )}

                    <DialogFooter className="flex-col-reverse gap-2 sm:flex-col-reverse sm:space-x-0">
                        <Button
                            type="button"
                            variant="outline"
                            className="h-11 w-full bg-transparent sm:w-full"
                            onClick={() => r && openMemoriaNovaAba(r.extratoId)}
                            disabled={!r}
                        >
                            <ExternalLink className="mr-2 h-4 w-4" />
                            Abrir memória de cálculo
                        </Button>
                        <Button
                            type="button"
                            className="h-11 w-full shadow-sm sm:w-full"
                            onClick={finalizeParaStep2}
                        >
                            Continuar
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </>
    );
}

