326	                        <Users className="h-3.5 w-3.5" />
327	                        Cessionários
328	                    </h3>
329	                    <div className="flex items-center gap-2">
330	                        <div className="relative">
331	                            <Search className="absolute left-2 top-1/2 h-3 w-3 -translate-y-1/2 text-muted-foreground dark:text-zinc-400" />
332	                            <input
333	                                type="text"
334	                                placeholder="Filtrar cessionários..."
335	                                value={searchTerm}
336	                                onChange={(e) => setSearchTerm(e.target.value)}
337	                                className="focus:ring-app-default/20 h-7 w-44 rounded-md border border-border bg-white pl-7 pr-2 text-[10px] outline-none focus:border-app-default focus:ring-1 disabled:cursor-not-allowed disabled:opacity-60 dark:border-white/15 dark:bg-boxdark dark:text-foreground dark:placeholder:text-zinc-500 dark:hover:border-white/25"
338	                            />
339	                        </div>
340	                        <button
341	                            type="button"
342	                            onClick={() => setShowCadastroCessionario(true)}
343	                            className="hover:bg-app-default/10 flex items-center gap-1 rounded-md border border-dashed border-app-default px-2 py-1 text-[10px] font-semibold text-app-default transition-colors disabled:cursor-not-allowed disabled:opacity-50 dark:border-app-default/50 dark:bg-app-default/10 dark:hover:bg-app-default/15"
344	                        >
345	                            <Plus className="h-3 w-3" />
346	                            Cadastrar novo
347	                        </button>
348	                    </div>
349	                </div>
350	
351	                {/* Tabela */}
352	                <div className="overflow-x-auto">
353	                    <table className="w-full min-w-[520px]">
354	                        <thead>
355	                            <tr>
356	                                <th className={`${thClass} text-left`}>
357	                                    Cessionário / Investidor
358	                                    <span className="ml-0.5 text-red-400">*</span>
359	                                </th>
360	                                <th className={`${thClass} text-left`}>Broker de Investidor</th>
361	                                <th className={`${thClass} w-20 text-right`}>
362	                                    % Adq.
363	                                    <span className="ml-0.5 text-red-400">*</span>
364	                                </th>
365	                                <th className={`${thClass} text-right`}>Vlr Líquido Adq.</th>
366	                                <th className={`${thClass} w-8`} />
367	                            </tr>
368	                        </thead>
369	                        <tbody>
370	                            {fields.map((field, idx) => {
371	                                const pctNum = parsePct(cessionarios[idx]?.pct ?? '');
372	                                const valorCalc = valorLiquido * (pctNum / 100);
373	                                return (
374	                                    <tr
