381	                                                    {idx + 1}
382	                                                </span>
383	                                                <div className="flex-1">
384	                                                    <Controller
385	                                                        control={control}
386	                                                        name={`cessionarios.${idx}.nome`}
387	                                                        render={({ field: f }) => (
388	                                                            <ProductCombobox
389	                                                                options={cedenteComboboxOptions}
390	                                                                value={f.value ?? ''}
391	                                                                onChange={(selectedValue) => {
392	                                                                    const opt =
