394	                                                                            (o) =>
395	                                                                                o.value ===
396	                                                                                selectedValue,
397	                                                                        );
398	                                                                    const inlineCessionarioId =
399	                                                                        opt?.inlineCessionarioId ||
400	                                                                        null;
401	                                                                    const cedenteId =
402	                                                                        opt?.cedenteId || null;
403	                                                                    const found = opt
404	                                                                        ? allCessionarios.find(
405	                                                                              (c) => {
406	                                                                                  if (
407	                                                                                      inlineCessionarioId &&
408	                                                                                      c.inlineCessionarioId
409	                                                                                  )
410	                                                                                      return (
411	                                                                                          c.inlineCessionarioId ===
412	                                                                                          inlineCessionarioId
413	                                                                                      );
414	                                                                                  if (
415	                                                                                      cedenteId &&
416	                                                                                      c.cedente_id
417	                                                                                  )
418	                                                                                      return (
419	                                                                                          c.cedente_id ===
420	                                                                                          cedenteId
421	                                                                                      );
422	                                                                                  return (
423	                                                                                      c.nome ===
424	                                                                                      selectedValue
425	                                                                                  );
426	                                                                              },
427	                                                                          )
428	                                                                        : allCessionarios.find(
429	                                                                              (c) =>
430	                                                                                  c.nome ===
431	                                                                                  selectedValue,
432	                                                                          );
433	
434	                                                                    f.onChange(
