'use client';

import { forwardRef, useState, useImperativeHandle, useEffect, useMemo, useRef } from 'react';
import { useForm, useFieldArray, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { AlertTriangle, Plus, Search, Settings, Users, X } from 'lucide-react';
import { formatBRL, parsePct } from '../../utils';
import { cn } from '@/lib/utils';
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select';
import {
    CadastroCessionarioModal,
    type PessoaCadastrada,
} from '@/components/PostAquisition/financial/Modals/CadastroCessionarioModal';
import { getCessionariosList } from '@/services/BrokerServices';
import { getResponsaveisWizard, type ResponsavelWizard } from '@/services/posAquisicao';

function formatNomeComUsername(nome: string, username?: string | null): string {
    const u = (username ?? '').trim();
    if (!u) return nome;
    return `${nome} (${u})`;
}

function formatBrokerDisplay(r: ResponsavelWizard): string {
    return formatNomeComUsername(r.nome, r.username);
}

function formatCoordenadorDisplay(c: NonNullable<ResponsavelWizard['coordenador']>): string {
    return formatNomeComUsername(c.nome, c.username);
}
import { useQuery } from '@tanstack/react-query';
import { ProductCombobox } from '@/design-system/components/product-combobox';
import { step2Schema, type Step2Values, type StepHandle } from './schemas';

interface StepComercialProps {
    defaultValues?: Step2Values;
    valorLiquido: number;
    onValidSubmit: (data: Step2Values) => void;
    onValidityChange?: (isValid: boolean) => void;
    onDirtyChange?: (isDirty: boolean) => void;
}

const labelClass =
    'text-[9px] font-semibold text-[#888] uppercase mb-0.5 dark:text-zinc-400';
const inputClass =
    'w-full h-8 px-2 py-0 text-xs rounded-md border border-border bg-white outline-none transition-colors focus:border-app-default focus:ring-1 focus:ring-app-default/20 dark:border-white/15 dark:bg-boxdark dark:text-foreground dark:placeholder:text-zinc-500 dark:hover:border-white/25 dark:focus:border-app-default dark:focus:ring-app-default/30';
const thClass =
    'text-[10px] font-semibold uppercase tracking-wide text-muted-foreground py-2 px-2 border-b border-border dark:border-white/10 dark:text-zinc-400';
const tdClass = 'py-1.5 px-2 align-middle';

const DEFAULT_VALUES: Step2Values = {
    cessionarios: [
        {
            id: crypto.randomUUID(),
            nome: '',
            pct: '',
            broker: '',
            cedente_id: null,
            inlineCessionarioId: null,
            cedente_pessoa: null,
        },
    ],
    finalidade: 'Investimento',
    gestaoPos: true,
    brokerAtivos: '',
    brokerAtivoId: null,
    coordenador: '',
    coordenadorId: null,
    remanescenTeConfirmado: false,
};

function FieldError({ message }: { message?: string }) {
    if (!message) return null;
    return <p className="mt-0.5 text-[9px] font-medium text-red-500">{message}</p>;
}

export const StepComercial = forwardRef<StepHandle, StepComercialProps>(
    ({ defaultValues, valorLiquido, onValidSubmit, onValidityChange, onDirtyChange }, ref) => {
        const [showCadastroCessionario, setShowCadastroCessionario] = useState(false);
        const [searchTerm, setSearchTerm] = useState('');

        // Cessionários cadastrados no backend
        const { data: backendCessionarios = [] } = useQuery({
            queryKey: ['cessionarios-lista'],
            queryFn: getCessionariosList,
        });

        // Responsáveis (brokers internos) filtrados por host
        const { data: responsaveis = [], isPending: isLoadingResponsaveis } = useQuery<
            ResponsavelWizard[]
        >({
            queryKey: ['responsaveis-wizard'],
            queryFn: getResponsaveisWizard,
        });

        // Cessionários locais criados inline via modal (ainda não persistidos)
        const [inlineCessionarios, setInlineCessionarios] = useState<
            Array<{
                nome: string;
                id: string;
                tipo: 'PF' | 'PJ';
                documento?: string;
                cedente: PessoaCadastrada;
            }>
        >([]);

        const allCessionarios = useMemo(() => {
            const backendItems = backendCessionarios.map((c) => ({
                nome: c.nome,
                cedente_id: c.id,
                inlineCessionarioId: null as null,
                tipo: (c.tipo?.toUpperCase() as 'PF' | 'PJ') || 'PF',
                documento: c.documento,
            }));
            const localItems = inlineCessionarios.map((c) => ({
                nome: c.nome,
                cedente_id: null as null,
                inlineCessionarioId: c.id,
                tipo: c.tipo,
                documento: c.documento,
                cedente: c.cedente,
            }));
            return [...backendItems, ...localItems];
        }, [backendCessionarios, inlineCessionarios]);

        const filteredCessionarios = useMemo(() => {
            if (!searchTerm.trim()) return allCessionarios;
            const lower = searchTerm.toLowerCase();
            return allCessionarios.filter(
                (c) =>
                    c.nome.toLowerCase().includes(lower) ||
                    c.documento?.toLowerCase().includes(lower),
            );
        }, [allCessionarios, searchTerm]);

        const cedenteComboboxOptions = useMemo(
            () =>
                filteredCessionarios.map((c) => ({
                    label: !c.cedente_id ? `${c.nome} (novo)` : c.nome,
                    value: c.nome,
                    nome: c.nome,
                    cedenteId: c.cedente_id ?? '',
                    inlineCessionarioId: c.inlineCessionarioId ?? '',
                    documento: c.documento ?? '',
                    tipo: c.tipo,
                })),
            [filteredCessionarios],
        );

        const brokerAtivosComboboxOptions = useMemo(
            () =>
                responsaveis.map((r) => ({
                    label: formatBrokerDisplay(r),
                    value: r.id,
                })),
            [responsaveis],
        );

        const form = useForm<Step2Values>({
            resolver: zodResolver(step2Schema),
            defaultValues: defaultValues ?? DEFAULT_VALUES,
            mode: 'onSubmit',
            reValidateMode: 'onChange',
        });

        useEffect(() => {
            form.reset(defaultValues ?? DEFAULT_VALUES);
        }, [defaultValues, form]);

        const {
            control,
            register,
            watch,
            getValues,
            setValue,
            formState: { errors, isValid, isDirty },
        } = form;

        useEffect(() => {
            onValidityChange?.(isValid);
        }, [isValid, onValidityChange]);

        const onDirtyChangeRef = useRef(onDirtyChange);
        onDirtyChangeRef.current = onDirtyChange;
        useEffect(() => {
            onDirtyChangeRef.current?.(isDirty);
            // eslint-disable-next-line react-hooks/exhaustive-deps
        }, [isDirty]);

        const { fields, append, remove } = useFieldArray({
            control,
            name: 'cessionarios',
        });

        useImperativeHandle(ref, () => ({
            submit: () => {
                form.handleSubmit((data) => onValidSubmit(enrichStep2Values(data)))();
            },
            isDirty: () => isDirty,
            resetDirty: () => form.reset(form.getValues()),
        }));

        const cessionarios = watch('cessionarios');
        const gestaoPos = watch('gestaoPos');
        const coordenador = watch('coordenador');
        const remanescenTeConfirmado = watch('remanescenTeConfirmado');
        const brokerAtivoIdWatch = watch('brokerAtivoId');
        const brokerAtivosNomeWatch = watch('brokerAtivos');

        const brokerSelectValue =
            brokerAtivoIdWatch ??
            responsaveis.find(
                (r) =>
                    formatBrokerDisplay(r) === brokerAtivosNomeWatch ||
                    r.nome === brokerAtivosNomeWatch,
            )?.id ??
            '';

        const totalPct = cessionarios.reduce((s, c) => s + parsePct(c.pct), 0);
        const pctRestante = 100 - totalPct;
        const showWarning = totalPct > 0 && totalPct < 100 && !remanescenTeConfirmado;

        useEffect(() => {
            const cessionariosAtuais = getValues('cessionarios');
            if (cessionariosAtuais.length !== 1) return;

            const pctAtual = String(cessionariosAtuais[0]?.pct ?? '').trim();
            if (pctAtual) return;

            setValue('cessionarios.0.pct', '100', { shouldValidate: true });
        }, [getValues, setValue]);

        function getPctRestanteParaNovoCessionario() {
            const totalAtual = getValues('cessionarios').reduce((s, c) => s + parsePct(c.pct), 0);
            const restante = Math.max(0, 100 - totalAtual);
            return String(restante);
        }

        function appendCessionarioComPctRestante() {
            append({
                id: crypto.randomUUID(),
                nome: '',
                pct: getPctRestanteParaNovoCessionario(),
                broker: '',
                cedente_id: null,
                inlineCessionarioId: null,
                cedente_pessoa: null,
            });
        }

        function handleNovoCessionario(pessoa: PessoaCadastrada) {
            if (!pessoa.nome) return;
            const tipo = pessoa.tipo === 'pj' ? 'PJ' : 'PF';
            const documento = pessoa.cpf || pessoa.cnpj;
            const inlineCessionarioId = crypto.randomUUID();

            setInlineCessionarios((prev) => [
                {
                    nome: pessoa.nome,
                    id: inlineCessionarioId,
                    tipo,
                    documento,
                    cedente: pessoa,
                },
                ...prev,
            ]);

            const currentCessionarios = getValues('cessionarios');
            const hasSingleEmptyRow =
                currentCessionarios.length === 1 && !currentCessionarios[0].nome;

            if (hasSingleEmptyRow) {
                setValue('cessionarios.0.nome', pessoa.nome, { shouldDirty: true });
                setValue('cessionarios.0.cedente_id', null);
                setValue('cessionarios.0.inlineCessionarioId', inlineCessionarioId);
                setValue('cessionarios.0.cedente_tipo', tipo);
                setValue('cessionarios.0.cedente_documento', documento ?? '');
                setValue('cessionarios.0.cedente_pessoa', pessoa);
            } else {
                append({
                    id: crypto.randomUUID(),
                    nome: pessoa.nome,
                    pct: getPctRestanteParaNovoCessionario(),
                    broker: '',
                    cedente_id: null,
                    inlineCessionarioId,
                    cedente_tipo: tipo,
                    cedente_documento: documento ?? '',
                    cedente_pessoa: pessoa,
                });
            }

            setShowCadastroCessionario(false);
        }

        function enrichStep2Values(data: Step2Values): Step2Values {
            return {
                ...data,
                cessionarios: data.cessionarios.map((cessionario) => {
                    if (cessionario.cedente_id) return cessionario;

                    const inlineMatch = inlineCessionarios.find(
                        (item) => item.id === cessionario.inlineCessionarioId,
                    );

                    return {
                        ...cessionario,
                        cedente_pessoa: cessionario.cedente_pessoa ?? inlineMatch?.cedente ?? null,
                        cedente_tipo: cessionario.cedente_tipo ?? inlineMatch?.tipo ?? null,
                        cedente_documento: cessionario.cedente_documento ?? inlineMatch?.documento,
                    };
                }),
            };
        }

        return (
            <div className="rounded-xl border border-border bg-gray-50 p-4 dark:border-white/10 dark:bg-boxdark dark:shadow-sm dark:shadow-black/20">
                {/* Header */}
                <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
                    <h3 className="flex items-center gap-1.5 text-xs font-semibold text-[#374151] dark:text-foreground">
                        <Users className="h-3.5 w-3.5" />
                        Cessionários
                    </h3>
                    <div className="flex items-center gap-2">
                        <div className="relative">
                            <Search className="absolute left-2 top-1/2 h-3 w-3 -translate-y-1/2 text-muted-foreground dark:text-zinc-400" />
                            <input
                                type="text"
                                placeholder="Filtrar cessionários..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="focus:ring-app-default/20 h-7 w-44 rounded-md border border-border bg-white pl-7 pr-2 text-[10px] outline-none focus:border-app-default focus:ring-1 disabled:cursor-not-allowed disabled:opacity-60 dark:border-white/15 dark:bg-boxdark dark:text-foreground dark:placeholder:text-zinc-500 dark:hover:border-white/25"
                            />
                        </div>
                        <button
                            type="button"
                            onClick={() => setShowCadastroCessionario(true)}
                            className="hover:bg-app-default/10 flex items-center gap-1 rounded-md border border-dashed border-app-default px-2 py-1 text-[10px] font-semibold text-app-default transition-colors disabled:cursor-not-allowed disabled:opacity-50 dark:border-app-default/50 dark:bg-app-default/10 dark:hover:bg-app-default/15"
                        >
                            <Plus className="h-3 w-3" />
                            Cadastrar novo
                        </button>
                    </div>
                </div>

                {/* Tabela */}
                <div className="overflow-x-auto">
                    <table className="w-full min-w-[520px]">
                        <thead>
                            <tr>
                                <th className={`${thClass} text-left`}>
                                    Cessionário / Investidor
                                    <span className="ml-0.5 text-red-400">*</span>
                                </th>
                                <th className={`${thClass} text-left`}>Broker de Investidor</th>
                                <th className={`${thClass} w-20 text-right`}>
                                    % Adq.
                                    <span className="ml-0.5 text-red-400">*</span>
                                </th>
                                <th className={`${thClass} text-right`}>Vlr Líquido Adq.</th>
                                <th className={`${thClass} w-8`} />
                            </tr>
                        </thead>
                        <tbody>
                            {fields.map((field, idx) => {
                                const pctNum = parsePct(cessionarios[idx]?.pct ?? '');
                                const valorCalc = valorLiquido * (pctNum / 100);
                                return (
                                    <tr
                                        key={field.id}
                                        className="border-b border-border/40 last:border-0 dark:border-white/10"
                                    >
                                        <td className={tdClass}>
                                            <div className="flex items-center gap-2">
                                                <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-app-default text-[10px] font-bold text-white">
                                                    {idx + 1}
                                                </span>
                                                <div className="flex-1">
                                                    <Controller
                                                        control={control}
                                                        name={`cessionarios.${idx}.nome`}
                                                        render={({ field: f }) => (
                                                            <ProductCombobox
                                                                options={cedenteComboboxOptions}
                                                                value={f.value ?? ''}
                                                                onChange={(selectedValue) => {
                                                                    const opt =
                                                                        cedenteComboboxOptions.find(
                                                                            (o) =>
                                                                                o.value ===
                                                                                selectedValue,
                                                                        );
                                                                    const inlineCessionarioId =
                                                                        opt?.inlineCessionarioId ||
                                                                        null;
                                                                    const cedenteId =
                                                                        opt?.cedenteId || null;
                                                                    const found = opt
                                                                        ? allCessionarios.find(
                                                                              (c) => {
                                                                                  if (
                                                                                      inlineCessionarioId &&
                                                                                      c.inlineCessionarioId
                                                                                  )
                                                                                      return (
                                                                                          c.inlineCessionarioId ===
                                                                                          inlineCessionarioId
                                                                                      );
                                                                                  if (
                                                                                      cedenteId &&
                                                                                      c.cedente_id
                                                                                  )
                                                                                      return (
                                                                                          c.cedente_id ===
                                                                                          cedenteId
                                                                                      );
                                                                                  return (
                                                                                      c.nome ===
                                                                                      selectedValue
                                                                                  );
                                                                              },
                                                                          )
                                                                        : allCessionarios.find(
                                                                              (c) =>
                                                                                  c.nome ===
                                                                                  selectedValue,
                                                                          );

                                                                    f.onChange(
                                                                        found?.nome ?? selectedValue,
                                                                    );
                                                                    setValue(
                                                                        `cessionarios.${idx}.cedente_id`,
                                                                        found?.cedente_id ?? null,
                                                                    );
                                                                    setValue(
                                                                        `cessionarios.${idx}.inlineCessionarioId`,
                                                                        found?.inlineCessionarioId ??
                                                                            null,
                                                                    );
                                                                    if (found) {
                                                                        setValue(
                                                                            `cessionarios.${idx}.cedente_tipo`,
                                                                            found.tipo,
                                                                        );
                                                                        setValue(
                                                                            `cessionarios.${idx}.cedente_documento`,
                                                                            found.documento ?? '',
                                                                        );
                                                                        setValue(
                                                                            `cessionarios.${idx}.cedente_pessoa`,
                                                                            'cedente' in found
                                                                                ? found.cedente
                                                                                : null,
                                                                        );
                                                                    } else {
                                                                        setValue(
                                                                            `cessionarios.${idx}.cedente_pessoa`,
                                                                            null,
                                                                        );
                                                                    }
                                                                }}
                                                                placeholder="Buscar cessionário..."
                                                                fullWidth
                                                                triggerClassName={cn(
                                                                    'dark:border-white/15 dark:bg-boxdark dark:hover:border-white/25',
                                                                    errors.cessionarios?.[idx]
                                                                        ?.nome && 'border-red-400',
                                                                )}
                                                            />
                                                        )}
                                                    />
                                                    <FieldError
                                                        message={
                                                            errors.cessionarios?.[idx]?.nome
                                                                ?.message
                                                        }
                                                    />
                                                </div>
                                            </div>
                                        </td>
                                        <td className={tdClass}>
                                            <input
                                                type="text"
                                                placeholder="Broker do investidor"
                                                className={cn(
                                                    inputClass,
                                                    errors.cessionarios?.[idx]?.broker &&
                                                        'border-red-400',
                                                )}
                                                {...register(`cessionarios.${idx}.broker`)}
                                            />
                                            <FieldError
                                                message={
                                                    errors.cessionarios?.[idx]?.broker?.message
                                                }
                                            />
                                        </td>
                                        <td className={tdClass}>
                                            <div>
                                                <input
                                                    type="text"
                                                    className={cn(
                                                        inputClass,
                                                        'w-20 text-right',
                                                    )}
                                                    placeholder="0"
                                                    {...register(`cessionarios.${idx}.pct`)}
                                                />
                                                <FieldError
                                                    message={
                                                        errors.cessionarios?.[idx]?.pct?.message
                                                    }
                                                />
                                            </div>
                                        </td>
                                        <td className={`${tdClass} text-right`}>
                                            <span
                                                className={`text-xs font-semibold tabular-nums ${
                                                    valorCalc > 0
                                                        ? 'text-green-600 dark:text-green-400'
                                                        : 'text-muted-foreground'
                                                }`}
                                            >
                                                {valorCalc > 0 ? formatBRL(valorCalc) : '—'}
                                            </span>
                                        </td>
                                        <td className={tdClass}>
                                            <button
                                                type="button"
                                                onClick={() => {
                                                    if (fields.length > 1) remove(idx);
                                                }}
                                                className="rounded p-1 text-muted-foreground transition-colors hover:bg-red-50 hover:text-red-600 disabled:cursor-not-allowed disabled:opacity-40 dark:hover:bg-red-950/40 dark:hover:text-red-400"
                                            >
                                                <X className="h-3.5 w-3.5" />
                                            </button>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>

                {/* Rodapé da tabela */}
                <div className="mt-3 flex items-center justify-between border-t border-border/40 pt-3 dark:border-white/10">
                    <button
                        type="button"
                        onClick={appendCessionarioComPctRestante}
                        className="hover:bg-app-default/5 flex items-center gap-1 rounded-md border border-dashed border-border px-3 py-1.5 text-xs font-semibold text-app-default transition-colors hover:border-app-default disabled:cursor-not-allowed disabled:opacity-50 dark:border-white/15 dark:hover:border-app-default/50 dark:hover:bg-app-default/10"
                    >
                        <Plus className="h-3.5 w-3.5" />
                        Adicionar cessionário
                    </button>

                    <div className="flex items-center gap-4">
                        <span className="text-[10px] font-medium text-muted-foreground">
                            Total:
                        </span>
                        <span
                            className={cn(
                                'text-sm font-bold tabular-nums',
                                totalPct === 100
                                    ? 'text-green-600 dark:text-green-400'
                                    : totalPct > 100
                                      ? 'text-red-600 dark:text-red-400'
                                      : 'text-amber-600 dark:text-amber-400',
                            )}
                        >
                            {totalPct.toFixed(0)}%
                        </span>
                        {valorLiquido > 0 && (
                            <span className="text-xs font-semibold tabular-nums text-muted-foreground">
                                {formatBRL(valorLiquido)}
                            </span>
                        )}
                    </div>
                </div>

                {/* Erro global de cessionários */}
                {errors.cessionarios?.root?.message && (
                    <FieldError message={errors.cessionarios.root.message} />
                )}

                {/* Banner de aviso — % não atingida */}
                {showWarning && (
                    <div className="mt-3 flex items-center justify-between gap-3 rounded-lg border border-amber-200 bg-amber-50 px-4 py-2.5 dark:border-amber-700/40 dark:bg-amber-950/20">
                        <div className="flex items-center gap-2.5">
                            <AlertTriangle className="h-3.5 w-3.5 shrink-0 text-amber-600 dark:text-amber-400" />
                            <p className="text-[11px] font-medium text-amber-800 dark:text-amber-300">
                                <span className="font-bold">{pctRestante.toFixed(0)}%</span> do
                                precatório sem cessão atribuída. Deseja adicionar outro cessionário
                                para a parte remanescente?
                            </p>
                        </div>
                        <div className="flex shrink-0 gap-2">
                            <button
                                type="button"
                                onClick={appendCessionarioComPctRestante}
                                className="rounded-md bg-amber-600 px-3 py-1 text-[11px] font-semibold text-white transition-colors hover:bg-amber-700 disabled:cursor-not-allowed disabled:opacity-50 dark:bg-amber-700 dark:hover:bg-amber-600"
                            >
                                Sim
                            </button>
                            <button
                                type="button"
                                onClick={() =>
                                    setValue('remanescenTeConfirmado', true, {
                                        shouldValidate: true,
                                    })
                                }
                                className="rounded-md border border-amber-300 bg-white px-3 py-1 text-[11px] font-semibold text-amber-700 transition-colors hover:bg-amber-100 disabled:cursor-not-allowed disabled:opacity-50 dark:border-amber-600 dark:bg-amber-950/30 dark:text-amber-300 dark:hover:bg-amber-900/40"
                            >
                                Não
                            </button>
                        </div>
                    </div>
                )}

                {/* Confirmação ativa */}
                {remanescenTeConfirmado && totalPct < 100 && (
                    <div className="mt-3 flex items-center justify-between gap-3 rounded-lg border border-blue-200 bg-blue-50 px-4 py-2 dark:border-blue-700/40 dark:bg-blue-950/20">
                        <p className="text-[11px] font-medium text-blue-700 dark:text-blue-300">
                            Parte remanescente ({pctRestante.toFixed(0)}%) confirmada como adquirida
                            por outro cessionário.
                        </p>
                        <button
                            type="button"
                            onClick={() =>
                                setValue('remanescenTeConfirmado', false, { shouldValidate: true })
                            }
                            className="text-[10px] font-semibold text-blue-600 underline hover:no-underline disabled:cursor-not-allowed disabled:opacity-50 dark:text-blue-400"
                        >
                            Desfazer
                        </button>
                    </div>
                )}

                {/* ── Seção: Broker / Coordenador (global) ── */}
                <div className="mt-4 rounded-lg border border-border bg-white p-4 shadow-sm dark:border-white/10 dark:bg-boxdark-2 dark:shadow-none">
                    <p className="mb-3 text-[9px] font-bold uppercase tracking-wider text-muted-foreground dark:text-zinc-400">
                        Responsáveis pela Operação
                    </p>
                    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                        {/* Broker / Ativos — combobox */}
                        <div>
                            <label className={cn(labelClass, 'flex items-center gap-1')}>
                                Broker / Ativos
                            </label>
                            <Controller
                                control={control}
                                name="brokerAtivos"
                                render={({ field: f }) => (
                                    <ProductCombobox
                                        options={brokerAtivosComboboxOptions}
                                        value={brokerSelectValue || ''}
                                        onChange={(id) => {
                                            if (!id) {
                                                f.onChange('');
                                                setValue('brokerAtivoId', null, {
                                                    shouldValidate: true,
                                                });
                                                setValue('coordenador', '', {
                                                    shouldValidate: true,
                                                });
                                                setValue('coordenadorId', null);
                                                return;
                                            }
                                            const r = responsaveis.find((x) => x.id === id);
                                            if (!r) return;
                                            f.onChange(formatBrokerDisplay(r));
                                            setValue('brokerAtivoId', r.id, {
                                                shouldValidate: true,
                                            });
                                            setValue(
                                                'coordenador',
                                                r.coordenador
                                                    ? formatCoordenadorDisplay(r.coordenador)
                                                    : '',
                                                { shouldValidate: true },
                                            );
                                            setValue('coordenadorId', r.coordenador?.id ?? null);
                                        }}
                                        placeholder={
                                            isLoadingResponsaveis
                                                ? 'Carregando brokers...'
                                                : responsaveis.length === 0
                                                  ? 'Nenhum broker disponível'
                                                  : 'Buscar broker / ativos...'
                                        }
                                        disabled={
                                            isLoadingResponsaveis || responsaveis.length === 0
                                        }
                                        fullWidth
                                        triggerClassName={cn(
                                            'dark:border-white/15 dark:bg-boxdark dark:hover:border-white/25',
                                            errors.brokerAtivos && 'border-red-400',
                                        )}
                                    />
                                )}
                            />
                            <FieldError message={errors.brokerAtivos?.message} />
                        </div>

                        {/* Coordenador — inferido automaticamente */}
                        <div>
                            <label className={cn(labelClass, 'flex items-center gap-1')}>
                                Coordenador
                            </label>
                            <input
                                type="text"
                                value={coordenador}
                                readOnly
                                placeholder="Inferido pelo broker"
                                className={cn(
                                    inputClass,
                                    'cursor-default bg-muted/30 text-muted-foreground dark:bg-white/5 dark:text-zinc-400',
                                    errors.coordenador && 'border-red-400',
                                )}
                            />
                            <FieldError message={errors.coordenador?.message} />
                        </div>
                    </div>
                </div>

                {/* ── Seção Configuração ── */}
                <div className="mt-4 border-t border-border pt-4 dark:border-white/10">
                    <h3 className="mb-3 flex items-center gap-1.5 text-xs font-semibold text-foreground/70 dark:text-zinc-300">
                        <Settings className="h-3.5 w-3.5" />
                        Configuração
                    </h3>
                    <div className="flex flex-wrap items-end gap-6">
                        <div className="flex min-w-[200px] flex-1 flex-col gap-1.5">
                            <label className={labelClass}>Finalidade</label>
                            <Controller
                                control={control}
                                name="finalidade"
                                render={({ field: f }) => (
                                    <Select
                                        value={f.value}
                                        onValueChange={f.onChange}
                                    >
                                        <SelectTrigger className="h-9 w-full border-border text-xs normal-case tracking-normal disabled:cursor-not-allowed disabled:opacity-60 dark:border-white/15 dark:bg-boxdark dark:text-foreground dark:hover:border-white/25">
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem
                                                value="Investimento"
                                                className="normal-case tracking-normal"
                                            >
                                                Investimento
                                            </SelectItem>
                                            <SelectItem
                                                value="Compensação"
                                                className="normal-case tracking-normal"
                                            >
                                                Compensação
                                            </SelectItem>
                                        </SelectContent>
                                    </Select>
                                )}
                            />
                            <FieldError message={errors.finalidade?.message} />
                        </div>
                        <div className="flex flex-col gap-1.5">
                            <label className={labelClass}>Gestão Pós-Aquisição</label>
                            <div className="flex h-9 overflow-hidden rounded-md border border-border text-xs font-semibold dark:border-white/15">
                                <button
                                    type="button"
                                    onClick={() =>
                                        setValue('gestaoPos', true, { shouldValidate: true })
                                    }
                                    className={cn(
                                        'px-5 transition-colors',
                                        gestaoPos
                                            ? 'bg-app-default text-white'
                                            : 'bg-transparent text-muted-foreground hover:bg-muted dark:hover:bg-white/5',
                                    )}
                                >
                                    SIM
                                </button>
                                <button
                                    type="button"
                                    onClick={() =>
                                        setValue('gestaoPos', false, { shouldValidate: true })
                                    }
                                    className={cn(
                                        'px-5 transition-colors',
                                        !gestaoPos
                                            ? 'bg-app-default text-white'
                                            : 'bg-transparent text-muted-foreground hover:bg-muted dark:hover:bg-white/5',
                                    )}
                                >
                                    NÃO
                                </button>
                            </div>
                        </div>
                    </div>
                </div>

                <CadastroCessionarioModal
                    open={showCadastroCessionario}
                    onOpenChange={setShowCadastroCessionario}
                    onCadastrar={handleNovoCessionario}
                />
            </div>
        );
    },
);

StepComercial.displayName = 'StepComercial';

