import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Progress } from '@/components/ui/progress';
import {
    Select,
    SelectContent,
    SelectGroup,
    SelectItem,
    SelectLabel,
    SelectSeparator,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select';
import { cn } from '@/lib/utils';
import {
    ArrowRight,
    Building2,
    Check,
    ChevronDown,
    ChevronRight,
    FileText,
    Pencil,
    Plus,
    Scale,
    Trash2,
    User,
    Users,
} from 'lucide-react';
import React, { useMemo } from 'react';
import type {
    TAnaliseDocumentoSlot,
    TAtoHonorario,
    TContratoHonorario,
    TProfissionalJuridico,
    TValorSucumbencia,
} from '../../../../types/dueItem';
import { notifyAnaliseConcludeBlocked } from '../../../../utils/analise-conclude-feedback';
import {
    getAtoHonorarioPendingRequirements,
    getHonorariosPendingRequirements,
} from '../../../../utils/analise-conclusao-guards';
import { StatusBadge } from '../../StatusBadge';
import {
    analiseSectionFooterClass,
    ConcluirSecaoBlock,
    editarBtnBase,
    fieldLabelBase,
    inputBase,
    removerBtnBase,
    ResumoDocumentoValue,
    SectionConcluida,
    Textarea,
    UploadButton,
    ValorToggle,
} from './SectionUi';
import { ProcuracaoDialog } from './dialogs/ProcuracaoDialog';
import { SubstabelecimentoDialog } from './dialogs/SubstabelecimentoDialog';
import type { TDraftProfissional } from './dialogs/types';
import { AnaliseStepGuide } from './section-ui/AnaliseStepGuide';
import type { TAtoTipoCategoria, TAtoTipoValue } from './section-ui/atoTipoOptions';
import { TIPOS_ATO_POR_CATEGORIA } from './section-ui/atoTipoOptions';
import type { TAnaliseSectionStatus } from './types';

interface HonorariosSectionProps {
    expanded: boolean;
    status: TAnaliseSectionStatus;
    title: string;
    embedded?: boolean;
    locked?: boolean;
    lockMessage?: string;
    onToggle: () => void;
    honorariosSucumbenciais: boolean | null;
    honorariosContratuais: boolean | null;
    valorSucumbencia: TValorSucumbencia;
    contratosHonorarios: TContratoHonorario[];
    profissionaisJuridicos: TProfissionalJuridico[];
    atosHonorarios: TAtoHonorario[];
    handleUpdateValorSucumbencia: (field: keyof TValorSucumbencia, value: unknown) => void;
    handleAddContratoHonorarios: () => void;
    handleRemoveContratoHonorarios: (id: number) => void;
    handleUpdateContratoHonorarios: (
        id: number,
        field: keyof TContratoHonorario,
        value: unknown,
    ) => void;
    handleAddAtoHonorario: () => void;
    handleUpdateAtoHonorario: (
        id: string | number,
        field: keyof TAtoHonorario,
        value: unknown,
    ) => void;
    handleRemoveAtoHonorario: (id: string | number) => void;
    handleAddProfissionalFromModal: (prof: Omit<TProfissionalJuridico, 'id'>) => void;
    handleUpdateProfissional: (id: number, update: Partial<TProfissionalJuridico>) => void;
    handleRemoveProfissional: (id: number) => void;
    setHonorariosConcluido: (v: boolean) => void;
    canConcluirHonorarios: boolean;
    onConcluirHonorarios: () => void;
    setResumoHonorarios: (v: string) => void;
    resumoHonorarios: string;
    honorariosConcluido: boolean;
    handleUploadAnaliseDocumento: (
        slot: TAnaliseDocumentoSlot,
        file: File,
        itemId?: string,
    ) => Promise<{ doc_id?: string; name?: string }>;
    handleDeleteAnaliseDocumento: (docId?: string | null) => Promise<void>;
}

export function HonorariosSection({
    expanded,
    status,
    title,
    embedded = false,
    locked = false,
    lockMessage,
    onToggle,
    honorariosSucumbenciais,
    honorariosContratuais,
    valorSucumbencia,
    contratosHonorarios,
    profissionaisJuridicos,
    atosHonorarios,
    handleUpdateValorSucumbencia,
    handleAddContratoHonorarios,
    handleRemoveContratoHonorarios,
    handleUpdateContratoHonorarios,
    handleAddAtoHonorario,
    handleUpdateAtoHonorario,
    handleRemoveAtoHonorario,
    handleAddProfissionalFromModal,
    handleUpdateProfissional,
    handleRemoveProfissional,
    setHonorariosConcluido,
    canConcluirHonorarios,
    onConcluirHonorarios,
    setResumoHonorarios,
    resumoHonorarios,
    honorariosConcluido,
    handleUploadAnaliseDocumento,
    handleDeleteAnaliseDocumento,
}: HonorariosSectionProps) {
    const parsePercent = (value: string | undefined | null) =>
        parseFloat(String(value || '').replace(',', '.')) || 0;

    const parseBRL = (value: string | undefined | null) => {
        if (!value) return 0;
        return (
            parseFloat(
                String(value)
                    .replace(/\s/g, '')
                    .replace('R$', '')
                    .replace(/\./g, '')
                    .replace(',', '.'),
            ) || 0
        );
    };

    const formatBRL = (value: number) =>
        value.toLocaleString('pt-BR', {
            style: 'currency',
            currency: 'BRL',
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
        });

    const getValorCalculadoContrato = (contrato: TContratoHonorario) => {
        if (contrato.modo_valor === 'percentual') {
            const percentual = parsePercent(contrato.percentual);
            const base = parseBRL(contrato.base_calculo);
            return percentual > 0 && base > 0 ? (percentual / 100) * base : 0;
        }
        return parseBRL(contrato.valor);
    };

    const tipoPessoaProfissional = (prof: TProfissionalJuridico): 'fisica' | 'juridica' => {
        const tipo = (prof.tipo || '').toLowerCase();
        return tipo === 'juridica' || tipo === 'pj' ? 'juridica' : 'fisica';
    };

    const profissionaisRaiz = profissionaisJuridicos.filter((p) => !p.substabelecido_de);
    const exibirHonorariosContratuais = !!honorariosContratuais;
    const exibirHonorariosSucumbenciais = !!honorariosSucumbenciais;

    const updateProfissional = <K extends keyof TProfissionalJuridico>(
        id: number,
        field: K,
        value: TProfissionalJuridico[K],
    ) => handleUpdateProfissional(id, { [field]: value } as Partial<TProfissionalJuridico>);

    const [expandedRows, setExpandedRows] = React.useState<Record<number, boolean>>({});
    const [procuracaoOpen, setProcuracaoOpen] = React.useState(false);
    const [substabelecimentoOpen, setSubstabelecimentoOpen] = React.useState(false);
    const [procuracaoDataConstituicao, setProcuracaoDataConstituicao] = React.useState('');
    const [substabelecimentoData, setSubstabelecimentoData] = React.useState('');
    const [substabelecimentoTipo, setSubstabelecimentoTipo] = React.useState<
        'com_reserva' | 'sem_reserva'
    >('com_reserva');
    const [substabelecidoDe, setSubstabelecidoDe] = React.useState<string>('');

    const createDraftProfissional = (): TDraftProfissional => ({
        id: Date.now() + Math.floor(Math.random() * 1000),
        tipo: 'fisica',
        nome: '',
        oab: '',
        razao_social: '',
        cnpj: '',
    });

    const [procuracaoDrafts, setProcuracaoDrafts] = React.useState<TDraftProfissional[]>([
        createDraftProfissional(),
    ]);
    const [substabelecimentoDrafts, setSubstabelecimentoDrafts] = React.useState<
        TDraftProfissional[]
    >([createDraftProfissional()]);

    const resetProcuracaoDialog = () => {
        setProcuracaoDataConstituicao('');
        setProcuracaoDrafts([createDraftProfissional()]);
    };

    const resetSubstabelecimentoDialog = () => {
        setSubstabelecimentoData('');
        setSubstabelecimentoTipo('com_reserva');
        setSubstabelecidoDe('');
        setSubstabelecimentoDrafts([createDraftProfissional()]);
    };

    const handleConfirmProcuracao = () => {
        const validos = procuracaoDrafts.filter((d) =>
            d.tipo === 'fisica' ? !!d.nome.trim() : !!d.razao_social.trim(),
        );
        if (validos.length === 0) return;

        validos.forEach((draft) => {
            handleAddProfissionalFromModal({
                tipo: draft.tipo,
                nome: draft.tipo === 'fisica' ? draft.nome : '',
                oab: draft.tipo === 'fisica' ? draft.oab : '',
                razao_social: draft.tipo === 'juridica' ? draft.razao_social : '',
                cnpj: draft.tipo === 'juridica' ? draft.cnpj : '',
