                aloc_contratuais: '',
                advogado_responsavel: '',
                atuacao: '',
                embotado: false,
                tipo_substab: null,
                substabelecido_de: null,
                contato: '',
                email: '',
                anexos: [],
            });
        });

        setProcuracaoOpen(false);
        resetProcuracaoDialog();
    };

    const handleConfirmSubstabelecimento = () => {
        const origemId = Number(substabelecidoDe);
        if (!origemId) return;

        const validos = substabelecimentoDrafts.filter((d) =>
            d.tipo === 'fisica' ? !!d.nome.trim() : !!d.razao_social.trim(),
