        if (validos.length === 0) return;

        validos.forEach((draft) => {
            handleAddProfissionalFromModal({
                tipo: draft.tipo,
                nome: draft.tipo === 'fisica' ? draft.nome : '',
                oab: draft.tipo === 'fisica' ? draft.oab : '',
                razao_social: draft.tipo === 'juridica' ? draft.razao_social : '',
                cnpj: draft.tipo === 'juridica' ? draft.cnpj : '',
                data_constituicao: null,
                data_substab: substabelecimentoData || null,
                aloc_sucumbenciais: '',
                aloc_contratuais: '',
                advogado_responsavel: '',
                atuacao: '',
                embotado: false,
                tipo_substab: substabelecimentoTipo,
                substabelecido_de: origemId,
                contato: '',
                email: '',
                anexos: [],
