        setSubstabelecimentoOpen(false);
        resetSubstabelecimentoDialog();
    };

    const getTotalAlocado = (field: 'aloc_contratuais' | 'aloc_sucumbenciais') =>
        profissionaisJuridicos.reduce((sum, p) => sum + parsePercent(p[field]), 0);

    const valorContratuaisTotal = contratosHonorarios.reduce(
        (sum, contrato) => sum + getValorCalculadoContrato(contrato),
