            : parseBRL(valorSucumbencia.valor_absoluto);

    const totalAlocadoContratuais = getTotalAlocado('aloc_contratuais');
    const totalAlocadoSucumbenciais = getTotalAlocado('aloc_sucumbenciais');

    const valorContratuaisDistribuido = (totalAlocadoContratuais / 100) * valorContratuaisTotal;
    const valorSucumbenciaisDistribuido = (totalAlocadoSucumbenciais / 100) * valorSucumbenciaTotal;

    const progressoDistribuicaoContratuais =
        valorContratuaisTotal > 0 ? (valorContratuaisDistribuido / valorContratuaisTotal) * 100 : 0;
    const progressoDistribuicaoSucumbenciais =
        valorSucumbenciaTotal > 0
