    const getNomeProfissional = (prof: TProfissionalJuridico) => {
        const tipoPessoa = tipoPessoaProfissional(prof);
        if (tipoPessoa === 'juridica') {
            return prof.razao_social || 'Profissional sem nome';
        }
        return prof.nome || 'Profissional sem nome';
    };

    const etapaHonorariosPending = useMemo(
        () =>
            getHonorariosPendingRequirements({
                honorariosSucumbenciais,
                honorariosContratuais,
                profissionaisJuridicos,
                contratosHonorarios,
                valorSucumbencia,
            }),
        [
            honorariosSucumbenciais,
            honorariosContratuais,
            profissionaisJuridicos,
            contratosHonorarios,
            valorSucumbencia,
        ],
    );

    const renderAlocacaoBar = (label: string, colorClass: string, alocado: number) => {
        const max = 100;
        const percentual = Math.max(0, Math.min((alocado / max) * 100, 100));
        const extrapolado = alocado > max;
        return (
            <div className="rounded-xl border border-gray-100 bg-white p-3 dark:border-[#1e1e2e] dark:bg-[#0d0d12]">
                <div className="mb-2 flex items-center justify-between text-[0.75rem] font-semibold">
                    <span className={cn('text-gray-500', colorClass)}>{label}</span>
                    <span className={cn('font-bold', colorClass)}>{alocado.toFixed(2)}%</span>
                </div>
                <div className="h-2 overflow-hidden rounded-full bg-gray-100 dark:bg-[#1a1a1f]">
                    <div
                        className={cn(
                            'h-full transition-all',
                            colorClass.includes('blue') ? 'bg-celer-blue' : 'bg-emerald-600',
