                                                                </div>
                                                                <div className="truncate pl-5 text-[0.62rem] text-gray-500 dark:text-[#a1a1aa]">
                                                                    {tipoPessoaProfissional(
                                                                        prof,
                                                                    ) === 'juridica' ? (
                                                                        <>
                                                                            <Building2
                                                                                size={11}
                                                                                className="mr-1 inline"
                                                                            />
                                                                            {prof.cnpj ||
                                                                                'Sem CNPJ'}
                                                                        </>
                                                                    ) : (
                                                                        <>
                                                                            <User
                                                                                size={11}
                                                                                className="mr-1 inline"
                                                                            />
                                                                            {prof.oab || 'Sem OAB'}
                                                                        </>
                                                                    )}
                                                                </div>
                                                            </div>
                                                            <div className="text-gray-600 text-center text-[0.66rem] dark:text-[#d4d4d8]">
                                                                {prof.data_substab ||
                                                                    prof.data_constituicao ||
                                                                    '—'}
                                                            </div>
                                                            <div className="text-center">
                                                                <span className="rounded bg-blue-500/15 px-2 py-0.5 text-[0.6rem] font-semibold text-blue-500">
                                                                    {isSub ? 'Subst.' : 'Procur.'}
                                                                </span>
                                                            </div>
                                                            <div className="text-center">
                                                                <span className="rounded bg-blue-500/15 px-2 py-0.5 text-[0.65rem] font-bold text-blue-500">
                                                                    {honorariosContratuais
                                                                        ? `${pctCont.toFixed(1)}%`
                                                                        : '—'}
                                                                </span>
                                                            </div>
                                                            <div className="text-center">
                                                                <span className="rounded bg-green-500/15 px-2 py-0.5 text-[0.65rem] font-bold text-green-500">
                                                                    {honorariosSucumbenciais
                                                                        ? `${pctSuc.toFixed(1)}%`
                                                                        : '—'}
                                                                </span>
                                                            </div>
                                                            <div className="text-right font-semibold text-gray-900 dark:text-[#f4f4f5]">
                                                                {formatBRL(
                                                                    valorProfCont + valorProfSuc,
                                                                )}
                                                            </div>
                                                            <div className="flex justify-center">
                                                                <button
                                                                    type="button"
                                                                    className={removerBtnBase}
                                                                    onClick={() =>
                                                                        handleRemoveProfissional(
                                                                            prof.id,
                                                                        )
                                                                    }
                                                                >
                                                                    <Trash2 size={12} />
                                                                </button>
                                                            </div>
                                                        </div>

                                                        {isExpanded && (
                                                            <div className="grid gap-3 border-b border-gray-100 bg-gray-50/70 px-4 py-3 dark:border-[#1f1f1f] dark:bg-[#12121a] md:grid-cols-2">
                                                                {honorariosContratuais && (
                                                                    <div className="rounded-lg border border-blue-500/20 bg-white p-3 dark:bg-[#0f0f15]">
                                                                        <div className="mb-2 flex items-center gap-1.5 text-[0.72rem] font-semibold text-blue-500">
                                                                            <FileText size={13} />
                                                                            Contratuais
                                                                        </div>
                                                                        <div className="flex items-end gap-2">
                                                                            <div className="flex-1">
                                                                                <label
                                                                                    className={
                                                                                        fieldLabelBase
                                                                                    }
                                                                                >
                                                                                    Participacao (%)
                                                                                </label>
                                                                                <Input
                                                                                    value={
                                                                                        prof.aloc_contratuais ||
                                                                                        ''
                                                                                    }
                                                                                    onChange={(e) =>
                                                                                        updateProfissional(
                                                                                            prof.id,
                                                                                            'aloc_contratuais',
                                                                                            e.target
                                                                                                .value,
                                                                                        )
                                                                                    }
                                                                                    className="h-9"
                                                                                />
                                                                            </div>
                                                                            <div className="min-w-[120px] text-right text-[0.72rem] font-semibold text-blue-500">
                                                                                {formatBRL(
                                                                                    valorProfCont,
                                                                                )}
                                                                            </div>
                                                                        </div>
                                                                    </div>
                                                                )}

                                                                {honorariosSucumbenciais && (
                                                                    <div className="rounded-lg border border-green-500/20 bg-white p-3 dark:bg-[#0f0f15]">
                                                                        <div className="mb-2 flex items-center gap-1.5 text-[0.72rem] font-semibold text-green-500">
                                                                            <Scale size={13} />
                                                                            Sucumbenciais
                                                                        </div>
                                                                        <div className="flex items-end gap-2">
                                                                            <div className="flex-1">
                                                                                <label
                                                                                    className={
                                                                                        fieldLabelBase
                                                                                    }
                                                                                >
                                                                                    Participacao (%)
                                                                                </label>
                                                                                <Input
                                                                                    value={
                                                                                        prof.aloc_sucumbenciais ||
                                                                                        ''
                                                                                    }
                                                                                    onChange={(e) =>
                                                                                        updateProfissional(
                                                                                            prof.id,
                                                                                            'aloc_sucumbenciais',
                                                                                            e.target
                                                                                                .value,
                                                                                        )
                                                                                    }
                                                                                    className="h-9"
                                                                                />
                                                                            </div>
                                                                            <div className="min-w-[120px] text-right text-[0.72rem] font-semibold text-green-500">
                                                                                {formatBRL(
                                                                                    valorProfSuc,
                                                                                )}
                                                                            </div>
                                                                        </div>
                                                                    </div>
                                                                )}
                                                            </div>
                                                        )}
                                                    </React.Fragment>
                                                );
                                            });
                                        })}
                                    </div>
                                )}

                                <div className="mt-3 flex flex-col gap-2 sm:flex-row">
                                    <Button
                                        type="button"
                                        variant="outline-default"
                                        className="h-9 text-[0.72rem]"
                                        onClick={() => setProcuracaoOpen(true)}
                                    >
                                        <Plus size={13} className="mr-1" /> Adicionar via Procuracao
                                    </Button>
                                    <Button
                                        type="button"
                                        variant="outline"
                                        className="h-9 text-[0.72rem]"
                                        onClick={() => setSubstabelecimentoOpen(true)}
                                        disabled={profissionaisRaiz.length === 0}
                                    >
                                        <Plus size={13} className="mr-1" /> Adicionar via
                                        Substabelecimento
                                    </Button>
                                </div>

                                <ProcuracaoDialog
                                    open={procuracaoOpen}
                                    onOpenChange={(open) => {
                                        setProcuracaoOpen(open);
                                        if (!open) resetProcuracaoDialog();
                                    }}
                                    procuracaoDataConstituicao={procuracaoDataConstituicao}
                                    setProcuracaoDataConstituicao={setProcuracaoDataConstituicao}
                                    procuracaoDrafts={procuracaoDrafts}
                                    setProcuracaoDrafts={setProcuracaoDrafts}
                                    createDraftProfissional={createDraftProfissional}
                                    onConfirm={handleConfirmProcuracao}
                                />

                                <SubstabelecimentoDialog
                                    open={substabelecimentoOpen}
                                    onOpenChange={(open) => {
                                        setSubstabelecimentoOpen(open);
                                        if (!open) resetSubstabelecimentoDialog();
                                    }}
                                    profissionaisRaiz={profissionaisRaiz}
                                    getNomeProfissional={getNomeProfissional}
                                    tipoPessoaProfissional={tipoPessoaProfissional}
                                    substabelecidoDe={substabelecidoDe}
                                    setSubstabelecidoDe={setSubstabelecidoDe}
                                    substabelecimentoTipo={substabelecimentoTipo}
                                    setSubstabelecimentoTipo={setSubstabelecimentoTipo}
                                    substabelecimentoData={substabelecimentoData}
                                    setSubstabelecimentoData={setSubstabelecimentoData}
                                    substabelecimentoDrafts={substabelecimentoDrafts}
                                    setSubstabelecimentoDrafts={setSubstabelecimentoDrafts}
                                    createDraftProfissional={createDraftProfissional}
                                    onConfirm={handleConfirmSubstabelecimento}
                                />

                                {profissionaisJuridicos.length > 0 &&
                                    (honorariosContratuais || honorariosSucumbenciais) && (
                                        <div className="mt-4 grid gap-2 md:grid-cols-2">
                                            {honorariosContratuais &&
                                                renderAlocacaoBar(
                                                    'Alocacao Contratuais',
                                                    'text-blue-500',
                                                    totalAlocadoContratuais,
                                                )}
                                            {honorariosSucumbenciais &&
                                                renderAlocacaoBar(
                                                    'Alocacao Sucumbenciais',
                                                    'text-green-500',
                                                    totalAlocadoSucumbenciais,
                                                )}
                                        </div>
                                    )}
                            </div>

                            <div className="mt-1">
                                <div className="mb-2 flex items-center justify-between">
                                    <div className="text-[0.68rem] font-bold uppercase tracking-[0.04em] text-gray-500 dark:text-[#71717a]">
                                        Documentos e Decisoes Relacionadas ({atosHonorarios.length})
                                    </div>
                                    <button
                                        type="button"
                                        className={cn(editarBtnBase, 'px-3 py-1.5 text-[0.72rem] font-semibold')}
                                        onClick={handleAddAtoHonorario}
                                    >
                                        <Plus size={14} /> Adicionar Documento/Decisao
                                    </button>
                                </div>

                                {atosHonorarios.length === 0 ? (
                                    <div className="rounded-xl border border-dashed border-gray-200 px-4 py-6 text-center text-[0.74rem] text-gray-500 dark:border-[#2a2a2a] dark:text-[#71717a]">
                                        Nenhum ato de honorarios adicionado.
                                    </div>
                                ) : (
                                    <div className="flex flex-col gap-2.5">
                                        {atosHonorarios.map((ato, idx) => {
                                            const tipoLabel =
                                                (ato.tipo || '').trim() || `Ato ${idx + 1}`;
                                            const concluido = !!ato.concluido;
                                            const dataAtoFormatada = ato.data
                                                ? new Date(
                                                    `${ato.data}T00:00:00`,
                                                ).toLocaleDateString('pt-BR')
                                                : '—';
                                            return (
                                                <div
                                                    key={String(ato.id ?? idx)}
                                                    className={cn(
                                                        'rounded-xl border bg-white p-4 dark:bg-[#0d0d12]',
                                                        concluido
                                                            ? 'border-green-500/35 bg-green-500/3'
                                                            : 'border-gray-100 dark:border-[#1e1e2e]',
                                                    )}
                                                >
                                                    {concluido ? (
                                                        <>
                                                            <div className="mb-4 flex items-center justify-between gap-3">
                                                                <div className="flex min-w-0 items-center gap-2">
                                                                    <span className="inline-flex max-w-[320px] items-center gap-1.5 truncate rounded bg-blue-500/15 px-2.5 py-1 text-[0.62rem] font-bold uppercase text-blue-500">
                                                                        <FileText size={12} />
                                                                        {tipoLabel}
                                                                    </span>
                                                                    <span className="inline-flex items-center gap-1.5 rounded bg-green-500/15 px-2.5 py-1 text-[0.62rem] font-semibold text-green-500">
                                                                        <Check size={12} />
                                                                        Concluido
                                                                    </span>
                                                                </div>
                                                                <div className="flex items-center gap-2">
                                                                    <button
                                                                        type="button"
                                                                        className="inline-flex items-center gap-1.5 rounded border border-blue-500/30 bg-blue-500/10 px-2.5 py-1 text-[0.68rem] font-semibold text-blue-500"
                                                                        onClick={() =>
                                                                            handleUpdateAtoHonorario(
                                                                                ato.id ?? idx,
                                                                                'concluido',
                                                                                false,
                                                                            )
                                                                        }
                                                                    >
                                                                        <Pencil size={12} />
                                                                        Editar
                                                                    </button>
                                                                    <button
                                                                        type="button"
                                                                        className="inline-flex h-6 w-6 items-center justify-center rounded border border-red-500/30 bg-red-500/10 text-red-500"
                                                                        onClick={() =>
                                                                            handleRemoveAtoHonorario(
                                                                                ato.id ?? idx,
                                                                            )
                                                                        }
                                                                    >
                                                                        <Trash2 size={12} />
                                                                    </button>
                                                                </div>
                                                            </div>

                                                            <div className="grid gap-4 md:grid-cols-[140px_minmax(220px,1fr)_150px_minmax(210px,1fr)]">
                                                                <div>
                                                                    <div className="text-[0.62rem] font-semibold uppercase tracking-[0.04em] text-gray-500 dark:text-[#71717a]">
                                                                        Data
                                                                    </div>
                                                                    <div className="mt-0.5 text-[1.05rem] font-semibold text-gray-900 dark:text-white">
                                                                        {dataAtoFormatada}
                                                                    </div>
                                                                </div>
                                                                <div>
                                                                    <div className="text-[0.62rem] font-semibold uppercase tracking-[0.04em] text-gray-500 dark:text-[#71717a]">
                                                                        Titulo
                                                                    </div>
                                                                    <div className="mt-0.5 text-[1.05rem] font-semibold text-gray-900 dark:text-white">
                                                                        {ato.titulo || '—'}
                                                                    </div>
                                                                </div>
                                                                <div>
                                                                    <div className="text-[0.62rem] font-semibold uppercase tracking-[0.04em] text-gray-500 dark:text-[#71717a]">
                                                                        ID nos Autos
                                                                    </div>
                                                                    <div className="mt-0.5 text-[1.05rem] font-semibold text-gray-900 dark:text-white">
                                                                        {ato.id_autos || '—'}
                                                                    </div>
                                                                </div>
                                                                <div>
                                                                    <div className="text-[0.62rem] font-semibold uppercase tracking-[0.04em] text-gray-500 dark:text-[#71717a]">
                                                                        Documento
                                                                    </div>
                                                                    <div className="mt-0.5">
                                                                        {ato.documento ? (
                                                                            <ResumoDocumentoValue
                                                                                file={ato.documento}
                                                                            />
                                                                        ) : (
                                                                            <span className="text-[1.02rem] font-semibold text-celer-muted">
                                                                                —
                                                                            </span>
                                                                        )}
                                                                    </div>
                                                                </div>
                                                            </div>

                                                            {ato.comentario && (
                                                                <div className="mt-3 border-t border-gray-100 pt-2.5 text-[0.95rem] italic text-gray-300 dark:border-[#1e1e2e] dark:text-[#c4c4c4]">
                                                                    &quot;{ato.comentario}&quot;
                                                                </div>
                                                            )}
                                                        </>
                                                    ) : (
                                                        <>
                                                            <div className="mb-3 flex items-center justify-between gap-2">
                                                                <div className="flex min-w-0 items-center gap-2">
                                                                    <span className="max-w-[300px] truncate rounded bg-blue-500/15 px-2 py-0.5 text-[0.62rem] font-bold uppercase text-blue-500">
                                                                        {tipoLabel}
                                                                    </span>
                                                                </div>
                                                                <div className="flex items-center gap-2">
                                                                    <button
                                                                        type="button"
                                                                        className="rounded border border-green-500/30 bg-green-500/10 px-2.5 py-1 text-[0.68rem] font-semibold text-green-500"
                                                                        onClick={() => {
                                                                            const pending =
                                                                                getAtoHonorarioPendingRequirements(
                                                                                    ato,
                                                                                );
                                                                            if (pending.length > 0) {
                                                                                notifyAnaliseConcludeBlocked(
                                                                                    pending,
                                                                                    'Não foi possível concluir o ato',
                                                                                );
                                                                                return;
                                                                            }
                                                                            handleUpdateAtoHonorario(
                                                                                ato.id ?? idx,
                                                                                'concluido',
                                                                                true,
                                                                            );
                                                                        }}
                                                                    >
                                                                        Concluir
                                                                    </button>
                                                                    <button
                                                                        type="button"
                                                                        className={removerBtnBase}
                                                                        onClick={() =>
                                                                            handleRemoveAtoHonorario(
                                                                                ato.id ?? idx,
                                                                            )
                                                                        }
                                                                    >
                                                                        <Trash2 size={12} />
                                                                    </button>
                                                                </div>
                                                            </div>

                                                            <div className="grid gap-3">
                                                                <div className="grid gap-3 md:grid-cols-2">
                                                                    <div className="flex flex-col gap-1.5">
                                                                        <label
                                                                            className={
                                                                                fieldLabelBase
                                                                            }
                                                                        >
                                                                            Tipo de Ato
                                                                        </label>
                                                                        <Select
                                                                            value={ato.tipo || ''}
                                                                            onValueChange={(
                                                                                value: string,
                                                                            ) =>
                                                                                handleUpdateAtoHonorario(
                                                                                    ato.id ?? idx,
                                                                                    'tipo',
                                                                                    value as TAtoTipoValue,
                                                                                )
                                                                            }
                                                                        >
                                                                            <SelectTrigger
                                                                                className={cn(
                                                                                    inputBase,
                                                                                    'h-[46px] py-0',
                                                                                )}
                                                                            >
                                                                                <SelectValue placeholder="Selecione o tipo de ato" />
                                                                            </SelectTrigger>
                                                                            <SelectContent>
                                                                                {TIPOS_ATO_POR_CATEGORIA.map(
                                                                                    (
                                                                                        grupo: TAtoTipoCategoria,
                                                                                        index,
                                                                                    ) => (
                                                                                        <div
                                                                                            key={
                                                                                                grupo.label
                                                                                            }
                                                                                        >
                                                                                            <SelectGroup>
                                                                                                <SelectLabel>
                                                                                                    {
                                                                                                        grupo.label
                                                                                                    }
                                                                                                </SelectLabel>
                                                                                                {grupo.items.map(
                                                                                                    (
                                                                                                        tipo,
                                                                                                    ) => (
                                                                                                        <SelectItem
                                                                                                            key={
                                                                                                                tipo
                                                                                                            }
                                                                                                            value={
                                                                                                                tipo
                                                                                                            }
                                                                                                        >
                                                                                                            {grupo.label ===
                                                                                                                'Outros'
                                                                                                                ? tipo.toUpperCase()
                                                                                                                : tipo}
                                                                                                        </SelectItem>
                                                                                                    ),
                                                                                                )}
                                                                                            </SelectGroup>
                                                                                            {index <
                                                                                                TIPOS_ATO_POR_CATEGORIA.length -
                                                                                                1 && (
                                                                                                    <SelectSeparator />
                                                                                                )}
                                                                                        </div>
                                                                                    ),
                                                                                )}
                                                                            </SelectContent>
                                                                        </Select>
                                                                    </div>

                                                                    <div className="flex flex-col gap-1.5">
                                                                        <label
                                                                            className={
                                                                                fieldLabelBase
                                                                            }
                                                                        >
                                                                            Data
                                                                        </label>
                                                                        <input
                                                                            type="date"
                                                                            className={cn(
                                                                                inputBase,
                                                                                'h-[46px] py-0',
                                                                            )}
                                                                            value={ato.data || ''}
                                                                            onChange={(e) =>
                                                                                handleUpdateAtoHonorario(
                                                                                    ato.id ?? idx,
                                                                                    'data',
                                                                                    e.target.value,
                                                                                )
                                                                            }
                                                                        />
                                                                    </div>
                                                                </div>

                                                                <div className="flex flex-col gap-1.5">
                                                                    <label
                                                                        className={fieldLabelBase}
                                                                    >
                                                                        Titulo / Descricao
                                                                    </label>
                                                                    <input
                                                                        type="text"
                                                                        className={cn(
                                                                            inputBase,
                                                                            'h-[46px] py-0',
                                                                        )}
                                                                        placeholder="Descreva o ato"
                                                                        value={ato.titulo || ''}
                                                                        onChange={(e) =>
                                                                            handleUpdateAtoHonorario(
                                                                                ato.id ?? idx,
                                                                                'titulo',
                                                                                e.target.value,
                                                                            )
                                                                        }
                                                                    />
                                                                </div>

                                                                <div className="grid gap-3 md:grid-cols-2">
                                                                    <div className="flex flex-col gap-1.5">
                                                                        <label
                                                                            className={
                                                                                fieldLabelBase
                                                                            }
                                                                        >
                                                                            ID nos Autos
                                                                        </label>
                                                                        <input
                                                                            type="text"
                                                                            className={cn(
                                                                                inputBase,
                                                                                'h-[46px] py-0',
                                                                            )}
                                                                            placeholder="Ex: fls. 80-90"
                                                                            value={
                                                                                ato.id_autos || ''
                                                                            }
                                                                            onChange={(e) =>
                                                                                handleUpdateAtoHonorario(
                                                                                    ato.id ?? idx,
                                                                                    'id_autos',
                                                                                    e.target.value,
                                                                                )
                                                                            }
                                                                        />
                                                                    </div>

                                                                    <div className="flex flex-col gap-1.5">
                                                                        <label
                                                                            className={
                                                                                fieldLabelBase
                                                                            }
                                                                        >
                                                                            Documento
                                                                        </label>
                                                                        <UploadButton
                                                                            file={
                                                                                ato.documento ||
                                                                                null
                                                                            }
                                                                            onUpload={async (
                                                                                f: File,
                                                                            ) => {
                                                                                const uploaded =
                                                                                    await handleUploadAnaliseDocumento(
                                                                                        'ato_honorario',
                                                                                        f,
                                                                                        String(
                                                                                            ato.id ??
                                                                                            idx,
                                                                                        ),
                                                                                    );
                                                                                handleUpdateAtoHonorario(
                                                                                    ato.id ?? idx,
                                                                                    'documento',
                                                                                    uploaded,
                                                                                );
                                                                            }}
                                                                            onRemove={async () => {
                                                                                await handleDeleteAnaliseDocumento(
                                                                                    ato.documento
                                                                                        ?.doc_id,
                                                                                );
                                                                                handleUpdateAtoHonorario(
                                                                                    ato.id ?? idx,
                                                                                    'documento',
                                                                                    null,
                                                                                );
                                                                            }}
                                                                        />
                                                                    </div>
                                                                </div>

                                                                <div className="flex flex-col gap-1.5">
                                                                    <label
                                                                        className={fieldLabelBase}
                                                                    >
                                                                        Comentario
                                                                    </label>
                                                                    <Textarea
                                                                        value={ato.comentario || ''}
                                                                        onChange={(v: string) =>
                                                                            handleUpdateAtoHonorario(
                                                                                ato.id ?? idx,
                                                                                'comentario',
                                                                                v,
                                                                            )
                                                                        }
                                                                        placeholder="Contexto do ato, efeitos e observacoes"
                                                                        rows={2}
                                                                    />
                                                                </div>
                                                            </div>
                                                        </>
                                                    )}
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>

                            <ConcluirSecaoBlock
                                labelResumo="Resumo dos Honorarios"
                                resumoValue={resumoHonorarios}
                                onChangeResumo={setResumoHonorarios}
                                onConcluir={onConcluirHonorarios}
                                disabled={!canConcluirHonorarios}
                                pendingRequirements={etapaHonorariosPending}
                                concludeBlockedTitle="Não foi possível concluir Honorários"
                                hint="Responda sucumbenciais/contratuais, cadastre profissionais, preencha valores e alocação de 100%."
                            />
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

content.content:
1	/**
2	 * Funções utilitárias para formatação e cálculos
3	 */
4	
5	import { COLORS, SCORE_LEVEL, withAlpha } from "../_constants/colors";
6	import { InteractionUrgency } from "../_types/dashboard";
7	
8	export function formatBRL(v: number): string {
9	  if (v >= 1000) return `R$${(v / 1000).toFixed(1)}B`;
10	  if (v >= 1) return `R$${v.toFixed(1)}M`;
11	  return `R$${(v * 1000).toFixed(0)}K`;
12	}
13	
14	/**
15	 * Quando days === 0 e há atIso (timestamp ISO), retorna "Xmin" ou "Xh".
16	 * Caso contrário retorna "Xd" ou "0d".
17	 */
18	export function formatDaysAgoLabel(
19	  days: number | null | undefined,
