/**
 * Funções utilitárias para formatação e cálculos
 */

import { COLORS, SCORE_LEVEL, withAlpha } from "../_constants/colors";
import { InteractionUrgency } from "../_types/dashboard";

export function formatBRL(v: number): string {
  if (v >= 1000) return `R$${(v / 1000).toFixed(1)}B`;
  if (v >= 1) return `R$${v.toFixed(1)}M`;
  return `R$${(v * 1000).toFixed(0)}K`;
}

/**
 * Quando days === 0 e há atIso (timestamp ISO), retorna "Xmin" ou "Xh".
 * Caso contrário retorna "Xd" ou "0d".
 */
export function formatDaysAgoLabel(
  days: number | null | undefined,
  atIso?: string | null
): string {
  if (days == null || days >= 999) return "Nunca";
  if (days > 0) return `${days}d`;
  if (!atIso) return "0d";
  const at = new Date(atIso).getTime();
  const now = Date.now();
  const diffMs = now - at;
  if (diffMs < 0) return "0d";
  const minutes = Math.floor(diffMs / (60 * 1000));
  const hours = Math.floor(diffMs / (60 * 60 * 1000));
  if (minutes < 60) return `${minutes}min`;
  return `${hours}h`;
}

export function getInterUrgency(
  days: number | null | undefined,
  atIso?: string | null
): InteractionUrgency {
  if (days == null || days >= 999) {
    return {
      color: COLORS.danger,
      bg: withAlpha(COLORS.danger, 0.13),
      label: "Nunca",
      level: "critical",
    };
  }
  const label = formatDaysAgoLabel(days, atIso);
  if (days <= 3) {
    return {
      color: COLORS.textMuted,
      bg: withAlpha(COLORS.border, 0.2),
      label,
      level: "ok",
    };
  }
  if (days <= 7) {
    return {
      color: COLORS.textDim,
      bg: withAlpha(COLORS.border, 0.25),
      label,
      level: "watch",
    };
  }
  if (days <= 14) {
    return {
      color: COLORS.text,
      bg: withAlpha(COLORS.border, 0.3),
      label,
      level: "warn",
    };
  }
  return {
    color: COLORS.danger,
    bg: withAlpha(COLORS.danger, 0.13),
    label,
    level: "critical",
  };
}

export function getCadUrgency(
  days: number | null | undefined,
  atIso?: string | null
): {
  color: string;
  bg: string;
  label: string;
  level: "ok" | "watch" | "warn" | "critical";
} {
  if (days == null || days >= 999) {
    return { color: COLORS.danger, bg: withAlpha(COLORS.danger, 0.13), label: "Nunca", level: "critical" };
  }
  const label = formatDaysAgoLabel(days, atIso);
  if (days <= 3) return { color: COLORS.textMuted, bg: withAlpha(COLORS.border, 0.2), label, level: "ok" };
  if (days <= 7) return { color: COLORS.textDim, bg: withAlpha(COLORS.border, 0.25), label, level: "watch" };
  if (days <= 14) return { color: COLORS.text, bg: withAlpha(COLORS.border, 0.3), label, level: "warn" };
  return { color: COLORS.danger, bg: withAlpha(COLORS.danger, 0.13), label, level: "critical" };
}

export function getBrokerStatus(score: number): {
  label: string;
  color: string;
} {
  if (score >= 80) return { label: "Ativo", color: COLORS.brand };
  if (score >= 50) return { label: "Atenção", color: COLORS.textDim };
  return { label: "Crítico", color: COLORS.textMuted };
}

export function getScoreLetter(score: number): keyof typeof SCORE_LEVEL {
  if (score >= 80) return "A";
  if (score >= 60) return "B";
  if (score >= 40) return "C";
  return "D";
}

export function getScoreColor(score: number): string {
  return SCORE_LEVEL[getScoreLetter(score)];
}

export function getHealthStatus(
  metric: { direction: "high" | "low"; green: number; yellow: number },
  value: number
): {
  color: string;
  statusLabel: string;
} {
  if (metric.direction === "high") {
    if (value >= metric.green) return { color: COLORS.green, statusLabel: "Saudável" };
    if (value >= metric.yellow) return { color: "#FBBF24", statusLabel: "Atenção" };
    return { color: COLORS.red, statusLabel: "Crítico" };
  } else {
    if (value <= metric.green) return { color: COLORS.green, statusLabel: "Saudável" };
    if (value <= metric.yellow) return { color: "#FBBF24", statusLabel: "Atenção" };
    return { color: COLORS.red, statusLabel: "Crítico" };
  }
}

export function calculateConversionRate(cadastros: number, concluidos: number): number {
  return cadastros > 0 ? Number(((concluidos / cadastros) * 100).toFixed(1)) : 0;
}

export function calculateArchivingRate(cadastros: number, arquivados: number): number {
  return cadastros > 0 ? Number(((arquivados / cadastros) * 100).toFixed(0)) : 0;
}

